_event_template table\nCREATE TABLE notification_event_template (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  event_type VARCHAR(255) NOT NULL,\n  event_name VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  category TEXT NOT NULL,\n  default_priority TEXT NOT NULL,\n  default_frequency TEXT NOT NULL,\n  default_channels TEXT NOT NULL,\n  can_customize_sound BOOLEAN NOT NULL,\n  can_customize_visual BOOLEAN NOT NULL,\n  examples TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- language_option table\nCREATE TABLE language_option (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  value VARCHAR(255) NOT NULL,\n  label VARCHAR(255) NOT NULL,\n  native_name VARCHAR(255) NOT NULL,\n  flag VARCHAR(255) NOT NULL,\n  rtl BOOLEAN NOT NULL,\n  completeness INTEGER NOT NULL,\n  region VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- theme_option table\nCREATE TABLE theme_option (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  value TEXT NOT NULL,\n  label VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  primary_colors TEXT NOT NULL,\n  accent_color VARCHAR(255) NOT NULL,\n  background_gradient VARCHAR(255) NOT NULL,\n  is_premium BOOLEAN NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- u_i_density_option table\nCREATE TABLE u_i_density_option (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  value TEXT NOT NULL,\n  label VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  spacing INTEGER NOT NULL,\n  font_size INTEGER NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- animation_intensity table\nCREATE TABLE animation_intensity (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  value TEXT NOT NULL,\n  label VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  transition_duration INTEGER NOT NULL,\n  effect_intensity INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- chess_notation_option table\nCREATE TABLE chess_notation_option (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  value VARCHAR(255) NOT NULL,\n  label VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  example VARCHAR(255) NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- startup_behavior_option table\nCREATE TABLE startup_behavior_option (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  value TEXT NOT NULL,\n  label VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  icon VARCHAR(255) NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- analysis_settings table\nCREATE TABLE analysis_settings (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  depth INTEGER NOT NULL,\n  multi_p_v INTEGER NOT NULL,\n  threads INTEGER NOT NULL,\n  hash_size INTEGER NOT NULL,\n  time_limit INTEGER,\n  contempt INTEGER,\n  PRIMARY KEY (id)\n);\n\n-- coordinate_settings table\nCREATE TABLE coordinate_settings (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  show BOOLEAN NOT NULL,\n  position TEXT NOT NULL,\n  style TEXT NOT NULL,\n  color_scheme TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- move_highlight_settings table\nCREATE TABLE move_highlight_settings (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  show_last_move BOOLEAN NOT NULL,\n  show_legal_moves BOOLEAN NOT NULL,\n  style TEXT NOT NULL,\n  color VARCHAR(255) NOT NULL,\n  opacity INTEGER NOT NULL,\n  show_check BOOLEAN NOT NULL,\n  check_color VARCHAR(255) NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- animation_settings table\nCREATE TABLE animation_settings (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  move_animation BOOLEAN NOT NULL,\n  speed TEXT NOT NULL,\n  capture_animation BOOLEAN NOT NULL,\n  promotion_animation BOOLEAN NOT NULL,\n  check_animation BOOLEAN NOT NULL,\n  checkmate_animation BOOLEAN NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- sound_settings table\nCREATE TABLE sound_settings (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  enabled BOOLEAN NOT NULL,\n  volume INTEGER NOT NULL,\n  move_sound TEXT NOT NULL,\n  capture_sound TEXT NOT NULL,\n  check_sound TEXT NOT NULL,\n  castling_sound TEXT NOT NULL,\n  promotion_sound TEXT NOT NULL,\n  game_end_sound TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- markup_settings table\nCREATE TABLE markup_settings (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  enable_arrows BOOLEAN NOT NULL,\n  arrow_style TEXT NOT NULL,\n  arrow_color VARCHAR(255) NOT NULL,\n  arrow_opacity INTEGER NOT NULL,\n  enable_square_highlight BOOLEAN NOT NULL,\n  square_highlight_color VARCHAR(255) NOT NULL,\n  square_highlight_opacity INTEGER NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- border_settings table\nCREATE TABLE border_settings (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  show BOOLEAN NOT NULL,\n  style TEXT NOT NULL,\n  width TEXT NOT NULL,\n  color VARCHAR(255) NOT NULL,\n  material TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- board_theme table\nCREATE TABLE board_theme (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  category TEXT NOT NULL,\n  material TEXT NOT NULL,\n  light_square VARCHAR(255) NOT NULL,\n  dark_square VARCHAR(255) NOT NULL,\n  border TEXT NOT NULL,\n  background TEXT NOT NULL,\n  piece_set TEXT NOT NULL,\n  preview_image VARCHAR(255) NOT NULL,\n  is_premium BOOLEAN NOT NULL,\n  is_unlocked BOOLEAN NOT NULL,\n  author VARCHAR(255) NOT NULL,\n  created_at INTEGER NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- board_settings table\nCREATE TABLE board_settings (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  theme TEXT NOT NULL,\n  size TEXT NOT NULL,\n  orientation TEXT NOT NULL,\n  coordinates TEXT NOT NULL,\n  highlighting TEXT NOT NULL,\n  animations TEXT NOT NULL,\n  sounds TEXT NOT NULL,\n  markup TEXT NOT NULL,\n  show_labels BOOLEAN NOT NULL,\n  enable_context_menu BOOLEAN NOT NULL,\n  enable_drag_drop BOOLEAN NOT NULL,\n  auto_queen BOOLEAN NOT NULL,\n  show_captured_pieces BOOLEAN NOT NULL,\n  show_move_clock BOOLEAN NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- board_settings_export table\nCREATE TABLE board_settings_export (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  version VARCHAR(255) NOT NULL,\n  exported_at INTEGER NOT NULL,\n  settings TEXT NOT NULL,\n  custom_themes TEXT NOT NULL,\n  metadata TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- board_preview_props table\nCREATE TABLE board_preview_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  settings TEXT NOT NULL,\n  position VARCHAR(255),\n  size TEXT,\n  interactive BOOLEAN,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- theme_selector_props table\nCREATE TABLE theme_selector_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  themes TEXT NOT NULL,\n  selected_theme TEXT NOT NULL,\n  on_theme_select TEXT NOT NULL,\n  show_premium BOOLEAN NOT NULL,\n  category_filter VARCHAR(255),\n  theme TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- piece_selector_props table\nCREATE TABLE piece_selector_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  piece_sets TEXT NOT NULL,\n  selected_piece_set TEXT NOT NULL,\n  on_piece_set_select TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- board_controls_props table\nCREATE TABLE board_controls_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  settings TEXT NOT NULL,\n  on_settings_change TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- board_settings_hook_return table\nCREATE TABLE board_settings_hook_return (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  settings TEXT NOT NULL,\n  available_themes TEXT NOT NULL,\n  custom_themes TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  is_saving BOOLEAN NOT NULL,\n  is_exporting BOOLEAN NOT NULL,\n  is_importing BOOLEAN NOT NULL,\n  update_settings TEXT NOT NULL,\n  select_theme TEXT NOT NULL,\n  reset_to_defaults TEXT NOT NULL,\n  save_settings TEXT NOT NULL,\n  export_settings TEXT NOT NULL,\n  import_settings TEXT NOT NULL,\n  create_custom_theme TEXT NOT NULL,\n  delete_custom_theme TEXT NOT NULL,\n  preview_settings TEXT NOT NULL,\n  apply_preview TEXT NOT NULL,\n  cancel_preview TEXT NOT NULL,\n  is_preview_mode BOOLEAN NOT NULL,\n  error VARCHAR(255) NOT NULL,\n  clear_error TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- theme_wizard_step table\nCREATE TABLE theme_wizard_step (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  completed BOOLEAN NOT NULL,\n  current BOOLEAN NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- theme_creation_data table\nCREATE TABLE theme_creation_data (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  basic TEXT NOT NULL,\n  colors TEXT NOT NULL,\n  materials TEXT NOT NULL,\n  advanced TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- support_channel table\nCREATE TABLE support_channel (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  icon TEXT NOT NULL,\n  response_time VARCHAR(255) NOT NULL,\n  availability VARCHAR(255) NOT NULL,\n  action VARCHAR(255) NOT NULL,\n  is_enabled BOOLEAN NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- contact_category table\nCREATE TABLE contact_category (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  label VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  icon TEXT NOT NULL,\n  priority TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- contact_form_data table\nCREATE TABLE contact_form_data (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  selected_category VARCHAR(255) NOT NULL,\n  subject VARCHAR(255) NOT NULL,\n  message VARCHAR(255) NOT NULL,\n  email VARCHAR(255) NOT NULL,\n  attach_files BOOLEAN NOT NULL,\n  include_system_info BOOLEAN NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- contact_form_errors table\nCREATE TABLE contact_form_errors (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  category VARCHAR(255),\n  subject VARCHAR(255),\n  message VARCHAR(255),\n  email VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- system_info table\nCREATE TABLE system_info (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  browser VARCHAR(255) NOT NULL,\n  os VARCHAR(255) NOT NULL,\n  screen VARCHAR(255) NOT NULL,\n  account_type VARCHAR(255) NOT NULL,\n  last_login VARCHAR(255) NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- contact_submission_response table\nCREATE TABLE contact_submission_response (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  ticket_id VARCHAR(255) NOT NULL,\n  estimated_response VARCHAR(255) NOT NULL,\n  is_success BOOLEAN NOT NULL,\n  message VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE contact_submission_response ADD FOREIGN KEY (ticket_id) REFERENCES ticket (id);\n\n-- contact_state table\nCREATE TABLE contact_state (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  form_data TEXT NOT NULL,\n  errors TEXT NOT NULL,\n  is_valid BOOLEAN NOT NULL,\n  is_submitting BOOLEAN NOT NULL,\n  is_submitted BOOLEAN NOT NULL,\n  support_channels TEXT NOT NULL,\n  contact_categories TEXT NOT NULL,\n  system_info TEXT NOT NULL,\n  submission_result TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- use_contact_return table\nCREATE TABLE use_contact_return (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  form_data TEXT NOT NULL,\n  errors TEXT NOT NULL,\n  is_submitting BOOLEAN NOT NULL,\n  is_submitted BOOLEAN NOT NULL,\n  support_channels TEXT NOT NULL,\n  contact_categories TEXT NOT NULL,\n  system_info TEXT NOT NULL,\n  submission_result TEXT NOT NULL,\n  update_form_field TEXT NOT NULL,\n  validate_form TEXT NOT NULL,\n  clear_form TEXT NOT NULL,\n  reset_submission_state TEXT NOT NULL,\n  handle_submit TEXT NOT NULL,\n  get_priority_color TEXT NOT NULL,\n  generate_ticket_id TEXT NOT NULL,\n  handle_back_to_help TEXT NOT NULL,\n  handle_send_another TEXT NOT NULL,\n  handle_quick_help_click TEXT NOT NULL,\n  handle_channel_action TEXT NOT NULL,\n  error VARCHAR(255) NOT NULL,\n  clear_error TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE use_contact_return ADD FOREIGN KEY (generate_ticket_id) REFERENCES generate_ticket (id);\n\n-- use_contact_options table\nCREATE TABLE use_contact_options (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  on_submit_success TEXT,\n  on_submit_error TEXT,\n  auto_fill_user_info BOOLEAN,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- forgot_password_state table\nCREATE TABLE forgot_password_state (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  is_loading BOOLEAN NOT NULL,\n  is_email_sent VARCHAR(255) NOT NULL,\n  error VARCHAR(255) NOT NULL,\n  email_value VARCHAR(255) NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- password_reset_request table\nCREATE TABLE password_reset_request (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  email VARCHAR(255) NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- password_reset_response table\nCREATE TABLE password_reset_response (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  success BOOLEAN NOT NULL,\n  message VARCHAR(255) NOT NULL,\n  request_id VARCHAR(255),\n  error VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE password_reset_response ADD FOREIGN KEY (request_id) REFERENCES request (id);\n\n-- email_sent_data table\nCREATE TABLE email_sent_data (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  email VARCHAR(255) NOT NULL,\n  timestamp INTEGER NOT NULL,\n  estimated_delivery_time VARCHAR(255) NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- password_reset_service table\nCREATE TABLE password_reset_service (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- email_config table\nCREATE TABLE email_config (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  provider VARCHAR(255) NOT NULL,\n  delivery_time TEXT NOT NULL,\n  failure_rate INTEGER NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- help_article table\nCREATE TABLE help_article (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  content VARCHAR(255) NOT NULL,\n  category TEXT NOT NULL,\n  content_type TEXT NOT NULL,\n  difficulty TEXT NOT NULL,\n  tags TEXT NOT NULL,\n  reading_time INTEGER NOT NULL,\n  author TEXT NOT NULL,\n  metadata TEXT NOT NULL,\n  related_articles TEXT NOT NULL,\n  prerequisites TEXT,\n  is_featured BOOLEAN NOT NULL,\n  is_trending BOOLEAN NOT NULL,\n  video_url VARCHAR(255),\n  video_thumbnail VARCHAR(255),\n  video_duration INTEGER,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- f_a_q_item table\nCREATE TABLE f_a_q_item (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  question VARCHAR(255) NOT NULL,\n  answer VARCHAR(255) NOT NULL,\n  category TEXT NOT NULL,\n  tags TEXT NOT NULL,\n  popularity INTEGER NOT NULL,\n  is_featured BOOLEAN NOT NULL,\n  related_articles TEXT NOT NULL,\n  metadata TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- search_result table\nCREATE TABLE search_result (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  type TEXT NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  category TEXT NOT NULL,\n  relevance INTEGER NOT NULL,\n  url VARCHAR(255) NOT NULL,\n  thumbnail VARCHAR(255),\n  metadata TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- category_info table\nCREATE TABLE category_info (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id TEXT NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  icon VARCHAR(255) NOT NULL,\n  color VARCHAR(255) NOT NULL,\n  article_count INTEGER NOT NULL,\n  featured_articles TEXT NOT NULL,\n  is_popular BOOLEAN NOT NULL,\n  subcategories TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- help_center_config table\nCREATE TABLE help_center_config (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  featured_articles TEXT NOT NULL,\n  popular_articles TEXT NOT NULL,\n  trending_topics TEXT NOT NULL,\n  quick_actions TEXT NOT NULL,\n  contact_options TEXT NOT NULL,\n  search_suggestions TEXT NOT NULL,\n  announcement TEXT,\n  PRIMARY KEY (id)\n);\n\n-- search_filters table\nCREATE TABLE search_filters (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  content_type TEXT NOT NULL,\n  category TEXT NOT NULL,\n  difficulty TEXT NOT NULL,\n  sort_by TEXT NOT NULL,\n  sort_order TEXT NOT NULL,\n  featured_only BOOLEAN NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- category_browser_props table\nCREATE TABLE category_browser_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  categories TEXT NOT NULL,\n  selected_category TEXT NOT NULL,\n  on_category_select TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- article_viewer_props table\nCREATE TABLE article_viewer_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  article TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  user_progress TEXT NOT NULL,\n  related_articles TEXT NOT NULL,\n  on_article_navigate TEXT NOT NULL,\n  on_feedback_submit TEXT NOT NULL,\n  on_bookmark_toggle TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- f_a_q_section_props table\nCREATE TABLE f_a_q_section_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  faqs TEXT NOT NULL,\n  search_query VARCHAR(255),\n  category_filter TEXT NOT NULL,\n  on_category_filter_change TEXT NOT NULL,\n  on_f_a_q_vote TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- help_center_hook_return table\nCREATE TABLE help_center_hook_return (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  articles TEXT NOT NULL,\n  faqs TEXT NOT NULL,\n  tutorials TEXT NOT NULL,\n  categories TEXT NOT NULL,\n  config TEXT NOT NULL,\n  current_article TEXT NOT NULL,\n  search_results TEXT NOT NULL,\n  search_query VARCHAR(255) NOT NULL,\n  search_filters TEXT NOT NULL,\n  user_progress TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  is_searching BOOLEAN NOT NULL,\n  selected_category TEXT NOT NULL,\n  show_search_filters BOOLEAN NOT NULL,\n  perform_search TEXT NOT NULL,\n  clear_search TEXT NOT NULL,\n  update_filters TEXT NOT NULL,\n  get_suggestions TEXT NOT NULL,\n  navigate_to_article TEXT NOT NULL,\n  navigate_to_category TEXT NOT NULL,\n  go_back TEXT NOT NULL,\n  submit_feedback TEXT NOT NULL,\n  toggle_bookmark TEXT NOT NULL,\n  mark_as_read TEXT NOT NULL,\n  start_tutorial TEXT NOT NULL,\n  get_featured_content TEXT NOT NULL,\n  get_popular_content TEXT NOT NULL,\n  get_related_content TEXT NOT NULL,\n  get_category_content TEXT NOT NULL,\n  track_page_view TEXT NOT NULL,\n  track_search TEXT NOT NULL,\n  track_user_action TEXT NOT NULL,\n  error VARCHAR(255) NOT NULL,\n  handle_view_change TEXT NOT NULL,\n  handle_search TEXT NOT NULL,\n  handle_category_select TEXT NOT NULL,\n  handle_article_select TEXT NOT NULL,\n  handle_f_a_q_vote TEXT NOT NULL,\n  clear_error TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- quiet_hours_period table\nCREATE TABLE quiet_hours_period (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  start_time VARCHAR(255) NOT NULL,\n  end_time VARCHAR(255) NOT NULL,\n  days_of_week TEXT NOT NULL,\n  enabled BOOLEAN NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- notification_channel_settings table\nCREATE TABLE notification_channel_settings (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  channel TEXT NOT NULL,\n  enabled BOOLEAN NOT NULL,\n  min_priority TEXT NOT NULL,\n  sound TEXT NOT NULL,\n  visual_style TEXT NOT NULL,\n  delivery_delay INTEGER NOT NULL,\n  respect_quiet_hours BOOLEAN NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- notification_event_settings table\nCREATE TABLE notification_event_settings (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  event_type TEXT NOT NULL,\n  event_name VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  enabled BOOLEAN NOT NULL,\n  priority TEXT NOT NULL,\n  frequency TEXT NOT NULL,\n  enabled_channels TEXT NOT NULL,\n  custom_sound TEXT,\n  custom_visual_style TEXT,\n  category TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- notification_instance table\nCREATE TABLE notification_instance (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  event_type TEXT NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  message VARCHAR(255) NOT NULL,\n  priority TEXT NOT NULL,\n  status TEXT NOT NULL,\n  timestamp INTEGER NOT NULL,\n  sent_channels TEXT NOT NULL,\n  data TEXT,\n  actions TEXT,\n  expires_at INTEGER,\n  is_grouped BOOLEAN,\n  group_id VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE notification_instance ADD FOREIGN KEY (group_id) REFERENCES group (id);\n\n-- notification_action table\nCREATE TABLE notification_action (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  label VARCHAR(255) NOT NULL,\n  type TEXT NOT NULL,\n  url VARCHAR(255),\n  handler VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- notification_rule table\nCREATE TABLE notification_rule (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  enabled BOOLEAN NOT NULL,\n  conditions TEXT NOT NULL,\n  actions TEXT NOT NULL,\n  cooldown_minutes INTEGER NOT NULL,\n  max_triggers_per_day INTEGER NOT NULL,\n  created_at INTEGER NOT NULL,\n  last_triggered INTEGER,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- notification_condition table\nCREATE TABLE notification_condition (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  field VARCHAR(255) NOT NULL,\n  operator TEXT NOT NULL,\n  value TEXT NOT NULL,\n  logical_operator TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- notification_rule_action table\nCREATE TABLE notification_rule_action (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  type TEXT NOT NULL,\n  config TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- notification_test table\nCREATE TABLE notification_test (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  event_type TEXT NOT NULL,\n  test_data TEXT NOT NULL,\n  test_channels TEXT NOT NULL,\n  expected_behavior VARCHAR(255) NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- notification_stats table\nCREATE TABLE notification_stats (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  total_sent INTEGER NOT NULL,\n  by_channel TEXT NOT NULL,\n  by_event_type TEXT NOT NULL,\n  by_priority TEXT NOT NULL,\n  read_rate INTEGER NOT NULL,\n  avg_time_to_read INTEGER NOT NULL,\n  dismissal_rate INTEGER NOT NULL,\n  active_hours TEXT NOT NULL,\n  recent_activity TEXT NOT NULL,\n  channel_effectiveness TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- notification_settings table\nCREATE TABLE notification_settings (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  enabled BOOLEAN NOT NULL,\n  channels TEXT NOT NULL,\n  events TEXT NOT NULL,\n  quiet_hours TEXT NOT NULL,\n  do_not_disturb TEXT NOT NULL,\n  grouping TEXT NOT NULL,\n  retention_days INTEGER NOT NULL,\n  custom_rules TEXT NOT NULL,\n  preview TEXT NOT NULL,\n  auto_cleanup TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- notification_center_props table\nCREATE TABLE notification_center_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  notifications TEXT NOT NULL,\n  show_unread_only BOOLEAN NOT NULL,\n  on_notification_click TEXT NOT NULL,\n  on_notification_dismiss TEXT NOT NULL,\n  on_mark_all_read TEXT NOT NULL,\n  on_archive_notification TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- alert_settings_props table\nCREATE TABLE alert_settings_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  channel_settings TEXT NOT NULL,\n  on_channel_settings_change TEXT NOT NULL,\n  available_sounds TEXT NOT NULL,\n  on_preview_sound TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- channel_settings_props table\nCREATE TABLE channel_settings_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  channel TEXT NOT NULL,\n  on_change TEXT NOT NULL,\n  is_available BOOLEAN NOT NULL,\n  capabilities TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- event_settings_props table\nCREATE TABLE event_settings_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  event_settings TEXT NOT NULL,\n  on_event_settings_change TEXT NOT NULL,\n  available_channels TEXT NOT NULL,\n  group_by_category BOOLEAN NOT NULL,\n  theme TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- quiet_hours_props table\nCREATE TABLE quiet_hours_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  quiet_hours TEXT NOT NULL,\n  do_not_disturb TEXT NOT NULL,\n  on_quiet_hours_change TEXT NOT NULL,\n  on_do_not_disturb_change TEXT NOT NULL,\n  available_exceptions TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- notification_rules_props table\nCREATE TABLE notification_rules_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  rules TEXT NOT NULL,\n  on_rules_change TEXT NOT NULL,\n  on_test_rule TEXT NOT NULL,\n  available_fields TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- notification_testing_props table\nCREATE TABLE notification_testing_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  tests TEXT NOT NULL,\n  on_run_test TEXT NOT NULL,\n  test_results TEXT NOT NULL,\n  is_running_test VARCHAR(255) NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- notification_history_props table\nCREATE TABLE notification_history_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  notifications TEXT NOT NULL,\n  current_page INTEGER NOT NULL,\n  total_pages INTEGER NOT NULL,\n  items_per_page INTEGER NOT NULL,\n  on_page_change TEXT NOT NULL,\n  on_bulk_action TEXT NOT NULL,\n  filters TEXT NOT NULL,\n  on_filters_change TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- notifications_hook_return table\nCREATE TABLE notifications_hook_return (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  settings TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  has_unsaved_changes BOOLEAN NOT NULL,\n  notifications TEXT NOT NULL,\n  unread_count INTEGER NOT NULL,\n  notification_stats TEXT NOT NULL,\n  update_settings TEXT NOT NULL,\n  update_channel_settings TEXT NOT NULL,\n  update_event_settings TEXT NOT NULL,\n  update_quiet_hours TEXT NOT NULL,\n  update_do_not_disturb TEXT NOT NULL,\n  add_custom_rule TEXT NOT NULL,\n  update_custom_rule TEXT NOT NULL,\n  remove_custom_rule TEXT NOT NULL,\n  mark_as_read TEXT NOT NULL,\n  mark_all_as_read TEXT NOT NULL,\n  dismiss_notification TEXT NOT NULL,\n  archive_notification TEXT NOT NULL,\n  bulk_action TEXT NOT NULL,\n  preview_sound TEXT NOT NULL,\n  test_notification TEXT NOT NULL,\n  run_diagnostics TEXT NOT NULL,\n  save_settings TEXT NOT NULL,\n  reset_to_defaults TEXT NOT NULL,\n  export_settings TEXT NOT NULL,\n  import_settings TEXT NOT NULL,\n  error VARCHAR(255) NOT NULL,\n  clear_error TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- notification_diagnostics table\nCREATE TABLE notification_diagnostics (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  system_status TEXT NOT NULL,\n  channel_status TEXT NOT NULL,\n  permissions TEXT NOT NULL,\n  config_issues TEXT NOT NULL,\n  performance TEXT NOT NULL,\n  test_results TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- timer_config table\nCREATE TABLE timer_config (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  auto_start BOOLEAN NOT NULL,\n  interval INTEGER NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- general_preferences table\nCREATE TABLE general_preferences (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  auto_save BOOLEAN NOT NULL,\n  show_tooltips BOOLEAN NOT NULL,\n  confirm_destructive_actions BOOLEAN NOT NULL,\n  remember_last_session BOOLEAN NOT NULL,\n  time_zone VARCHAR(255) NOT NULL,\n  date_format TEXT NOT NULL,\n  time_format TEXT NOT NULL,\n  show_advanced_features BOOLEAN NOT NULL,\n  enable_keyboard_shortcuts BOOLEAN NOT NULL,\n  startup_behavior TEXT NOT NULL,\n  custom_startup_page VARCHAR(255),\n  PRIMARY KEY (id)\n);\n\n-- appearance_preferences table\nCREATE TABLE appearance_preferences (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  current_theme TEXT NOT NULL,\n  favorite_themes TEXT NOT NULL,\n  dark_mode BOOLEAN NOT NULL,\n  high_contrast BOOLEAN NOT NULL,\n  font_size INTEGER NOT NULL,\n  ui_density TEXT NOT NULL,\n  animations TEXT NOT NULL,\n  color_customization TEXT NOT NULL,\n  layout TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- language_preferences table\nCREATE TABLE language_preferences (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  current_language TEXT NOT NULL,\n  fallback_language TEXT NOT NULL,\n  region VARCHAR(255) NOT NULL,\n  currency VARCHAR(255) NOT NULL,\n  number_format TEXT NOT NULL,\n  piece_notation TEXT NOT NULL,\n  move_notation TEXT NOT NULL,\n  show_translations BOOLEAN NOT NULL,\n  auto_detect_language BOOLEAN NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- accessibility_preferences table\nCREATE TABLE accessibility_preferences (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  screen_reader TEXT NOT NULL,\n  keyboard TEXT NOT NULL,\n  visual TEXT NOT NULL,\n  audio TEXT NOT NULL,\n  motor TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- performance_preferences table\nCREATE TABLE performance_preferences (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  performance_level TEXT NOT NULL,\n  graphics TEXT NOT NULL,\n  memory TEXT NOT NULL,\n  network TEXT NOT NULL,\n  advanced TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- privacy_preferences table\nCREATE TABLE privacy_preferences (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  data_collection TEXT NOT NULL,\n  privacy TEXT NOT NULL,\n  sharing TEXT NOT NULL,\n  security TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- import_export_preferences table\nCREATE TABLE import_export_preferences (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  export_format TEXT NOT NULL,\n  export_includes TEXT NOT NULL,\n  import_validation TEXT NOT NULL,\n  auto_export TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- backup_sync_preferences table\nCREATE TABLE backup_sync_preferences (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  cloud_sync TEXT NOT NULL,\n  local_backup TEXT NOT NULL,\n  sync_scope TEXT NOT NULL,\n  restore TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- gaming_preferences table\nCREATE TABLE gaming_preferences (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  board TEXT NOT NULL,\n  game_u_i TEXT NOT NULL,\n  training TEXT NOT NULL,\n  competitive TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- sound_animation_preferences table\nCREATE TABLE sound_animation_preferences (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  sound TEXT NOT NULL,\n  animation TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- user_preferences table\nCREATE TABLE user_preferences (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  general TEXT NOT NULL,\n  appearance TEXT NOT NULL,\n  language TEXT NOT NULL,\n  accessibility TEXT NOT NULL,\n  performance TEXT NOT NULL,\n  privacy TEXT NOT NULL,\n  import_export TEXT NOT NULL,\n  backup_sync TEXT NOT NULL,\n  gaming TEXT NOT NULL,\n  sound_animation TEXT NOT NULL,\n  version VARCHAR(255) NOT NULL,\n  last_modified INTEGER NOT NULL,\n  user_id VARCHAR(255) NOT NULL,\n  PRIMARY KEY (id)\n);\nALTER TABLE user_preferences ADD FOREIGN KEY (user_id) REFERENCES user (id);\n\n-- preferences_section table\nCREATE TABLE preferences_section (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  icon VARCHAR(255) NOT NULL,\n  category TEXT NOT NULL,\n  badge VARCHAR(255),\n  is_new BOOLEAN,\n  is_pro BOOLEAN,\n  PRIMARY KEY (id)\n);\n\n-- preferences_validation table\nCREATE TABLE preferences_validation (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  is_valid BOOLEAN NOT NULL,\n  errors TEXT NOT NULL,\n  warnings TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- preferences_import_result table\nCREATE TABLE preferences_import_result (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  success BOOLEAN NOT NULL,\n  imported INTEGER NOT NULL,\n  skipped INTEGER NOT NULL,\n  errors TEXT NOT NULL,\n  warnings TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- preferences_hook_return table\nCREATE TABLE preferences_hook_return (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  preferences TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  is_saving BOOLEAN NOT NULL,\n  is_importing BOOLEAN NOT NULL,\n  is_exporting BOOLEAN NOT NULL,\n  update_general TEXT NOT NULL,\n  update_appearance TEXT NOT NULL,\n  update_language TEXT NOT NULL,\n  update_accessibility TEXT NOT NULL,\n  update_performance TEXT NOT NULL,\n  update_privacy TEXT NOT NULL,\n  update_import_export TEXT NOT NULL,\n  update_backup_sync TEXT NOT NULL,\n  update_gaming TEXT NOT NULL,\n  update_sound_animation TEXT NOT NULL,\n  update_multiple TEXT NOT NULL,\n  reset_to_defaults TEXT NOT NULL,\n  export_preferences TEXT NOT NULL,\n  import_preferences TEXT NOT NULL,\n  validate_preferences TEXT NOT NULL,\n  has_unsaved_changes BOOLEAN NOT NULL,\n  save_changes TEXT NOT NULL,\n  discard_changes TEXT NOT NULL,\n  error VARCHAR(255) NOT NULL,\n  clear_error TEXT NOT NULL,\n  handle_back TEXT NOT NULL,\n  handle_save TEXT NOT NULL,\n  handle_discard TEXT NOT NULL,\n  handle_reset TEXT NOT NULL,\n  handle_export TEXT NOT NULL,\n  handle_quick_preset TEXT NOT NULL,\n  get_section_info TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- general_settings_props table\nCREATE TABLE general_settings_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  preferences TEXT NOT NULL,\n  on_update TEXT NOT NULL,\n  is_loading BOOLEAN,\n  theme TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- theme_selector_props table\nCREATE TABLE theme_selector_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  preferences TEXT NOT NULL,\n  on_update TEXT NOT NULL,\n  is_loading BOOLEAN,\n  theme TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- language_settings_props table\nCREATE TABLE language_settings_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  preferences TEXT NOT NULL,\n  on_update TEXT NOT NULL,\n  is_loading BOOLEAN,\n  theme TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- accessibility_settings_props table\nCREATE TABLE accessibility_settings_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  preferences TEXT NOT NULL,\n  on_update TEXT NOT NULL,\n  is_loading BOOLEAN,\n  theme TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- performance_settings_props table\nCREATE TABLE performance_settings_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  preferences TEXT NOT NULL,\n  on_update TEXT NOT NULL,\n  is_loading BOOLEAN,\n  theme TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- privacy_settings_props table\nCREATE TABLE privacy_settings_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  preferences TEXT NOT NULL,\n  on_update TEXT NOT NULL,\n  is_loading BOOLEAN,\n  theme TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- import_export_settings_props table\nCREATE TABLE import_export_settings_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  preferences TEXT NOT NULL,\n  on_update TEXT NOT NULL,\n  on_export TEXT NOT NULL,\n  on_import TEXT NOT NULL,\n  is_loading BOOLEAN,\n  theme TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- backup_sync_settings_props table\nCREATE TABLE backup_sync_settings_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  preferences TEXT NOT NULL,\n  on_update TEXT NOT NULL,\n  is_loading BOOLEAN,\n  theme TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- gaming_settings_props table\nCREATE TABLE gaming_settings_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  preferences TEXT NOT NULL,\n  on_update TEXT NOT NULL,\n  is_loading BOOLEAN,\n  theme TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- sound_animation_settings_props table\nCREATE TABLE sound_animation_settings_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  preferences TEXT NOT NULL,\n  on_update TEXT NOT NULL,\n  is_loading BOOLEAN,\n  theme TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- quick_action table\nCREATE TABLE quick_action (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  icon VARCHAR(255) NOT NULL,\n  color VARCHAR(255) NOT NULL,\n  link VARCHAR(255) NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- quick_action table\nCREATE TABLE quick_action (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  icon TEXT NOT NULL,\n  path VARCHAR(255) NOT NULL,\n  color VARCHAR(255) NOT NULL,\n  background_color VARCHAR(255) NOT NULL,\n  is_recommended BOOLEAN,\n  priority INTEGER NOT NULL,\n  estimated_time INTEGER,\n  streak INTEGER,\n  PRIMARY KEY (id)\n);\n\n-- quick_actions_props table\nCREATE TABLE quick_actions_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  actions TEXT NOT NULL,\n  is_loading BOOLEAN,\n  max_actions INTEGER,\n  theme TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- command_center_theme table\nCREATE TABLE command_center_theme (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  command_primary VARCHAR(255) NOT NULL,\n  command_secondary VARCHAR(255) NOT NULL,\n  command_accent VARCHAR(255) NOT NULL,\n  status_colors TEXT NOT NULL,\n  hud_colors TEXT NOT NULL,\n  animations TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- password_requirement table\nCREATE TABLE password_requirement (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  regex TEXT NOT NULL,\n  text VARCHAR(255) NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- reset_password_state table\nCREATE TABLE reset_password_state (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  show_password VARCHAR(255) NOT NULL,\n  show_confirm_password VARCHAR(255) NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  is_success BOOLEAN NOT NULL,\n  error VARCHAR(255) NOT NULL,\n  is_valid_token BOOLEAN NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- token_validation_result table\nCREATE TABLE token_validation_result (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  is_valid BOOLEAN NOT NULL,\n  error VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- reset_password_response table\nCREATE TABLE reset_password_response (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  success BOOLEAN NOT NULL,\n  message VARCHAR(255),\n  error VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- reset_password_config table\nCREATE TABLE reset_password_config (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  token VARCHAR(255),\n  navigate TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- quick_start_guide table\nCREATE TABLE quick_start_guide (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  target_user TEXT NOT NULL,\n  essential_tutorials TEXT NOT NULL,\n  estimated_time INTEGER NOT NULL,\n  steps TEXT NOT NULL,\n  reward TEXT,\n  PRIMARY KEY (id)\n);\n\n-- interactive_guide_props table\nCREATE TABLE interactive_guide_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  tutorial TEXT NOT NULL,\n  progress TEXT NOT NULL,\n  current_step INTEGER NOT NULL,\n  on_step_complete TEXT NOT NULL,\n  on_step_skip TEXT NOT NULL,\n  on_tutorial_complete TEXT NOT NULL,\n  on_pause TEXT NOT NULL,\n  on_resume TEXT NOT NULL,\n  on_restart TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- ========================================
-- PUZZLE DOMAIN
