-- collection_browser_tab table\nCREATE TABLE collection_browser_tab (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  key TEXT NOT NULL,\n  label VARCHAR(255) NOT NULL,\n  icon VARCHAR(255) NOT NULL,\n  description VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- endgame_puzzle table\nCREATE TABLE endgame_puzzle (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id INTEGER NOT NULL,\n  fen VARCHAR(255) NOT NULL,\n  solution TEXT NOT NULL,\n  endgame_type VARCHAR(255) NOT NULL,\n  difficulty TEXT NOT NULL,\n  rating INTEGER NOT NULL,\n  moves INTEGER NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  theory VARCHAR(255) NOT NULL,\n  hint1 VARCHAR(255) NOT NULL,\n  hint2 VARCHAR(255) NOT NULL,\n  hint3 VARCHAR(255) NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- endgame_category table\nCREATE TABLE endgame_category (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  name VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  puzzles INTEGER NOT NULL,\n  completed INTEGER NOT NULL,\n  icon TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- piece_customization table\nCREATE TABLE piece_customization (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  size_scaling INTEGER NOT NULL,\n  shadow_effect TEXT NOT NULL,\n  border_enabled BOOLEAN NOT NULL,\n  border_width INTEGER NOT NULL,\n  border_color VARCHAR(255) NOT NULL,\n  glow_effect BOOLEAN NOT NULL,\n  glow_color VARCHAR(255) NOT NULL,\n  glow_intensity INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- puzzle_source_metadata table\nCREATE TABLE puzzle_source_metadata (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  source_id VARCHAR(255) NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  total_puzzles INTEGER NOT NULL,\n  average_rating INTEGER NOT NULL,\n  categories TEXT NOT NULL,\n  is_active BOOLEAN NOT NULL,\n  last_updated VARCHAR(255) NOT NULL,\n  import_date VARCHAR(255) NOT NULL,\n  attribution TEXT NOT NULL,\n  statistics TEXT NOT NULL,\n  created_at VARCHAR(255) NOT NULL,\n  updated_at VARCHAR(255) NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE puzzle_source_metadata ADD FOREIGN KEY (source_id) REFERENCES source (id);\n\n-- puzzle_source_mapping table\nCREATE TABLE puzzle_source_mapping (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  source TEXT NOT NULL,\n  label VARCHAR(255) NOT NULL,\n  icon VARCHAR(255) NOT NULL,\n  short_icon VARCHAR(255) NOT NULL,\n  color VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- tactical_puzzle table\nCREATE TABLE tactical_puzzle (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id INTEGER NOT NULL,\n  fen VARCHAR(255) NOT NULL,\n  solution TEXT NOT NULL,\n  theme VARCHAR(255) NOT NULL,\n  difficulty TEXT NOT NULL,\n  rating INTEGER NOT NULL,\n  moves INTEGER NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  hint1 VARCHAR(255) NOT NULL,\n  hint2 VARCHAR(255) NOT NULL,\n  hint3 VARCHAR(255) NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- puzzle_selection_entry table\nCREATE TABLE puzzle_selection_entry (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  timestamp VARCHAR(255) NOT NULL,\n  puzzle_id VARCHAR(255) NOT NULL,\n  selection_reason VARCHAR(255) NOT NULL,\n  user_rating INTEGER NOT NULL,\n  puzzle_rating INTEGER NOT NULL,\n  theme VARCHAR(255) NOT NULL,\n  difficulty VARCHAR(255) NOT NULL,\n  was_skipped BOOLEAN NOT NULL,\n  performance INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE puzzle_selection_entry ADD FOREIGN KEY (puzzle_id) REFERENCES puzzle (id);\n\n-- user_puzzle_session table\nCREATE TABLE user_puzzle_session (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  session_id VARCHAR(255) NOT NULL,\n  user_id VARCHAR(255) NOT NULL,\n  start_time VARCHAR(255) NOT NULL,\n  end_time VARCHAR(255),\n  puzzles_solved INTEGER NOT NULL,\n  correct_answers INTEGER NOT NULL,\n  total_time INTEGER NOT NULL,\n  average_time INTEGER NOT NULL,\n  selected_difficulties TEXT NOT NULL,\n  selected_themes TEXT NOT NULL,\n  session_type TEXT NOT NULL,\n  results TEXT NOT NULL,\n  session_stats TEXT NOT NULL,\n  created_at VARCHAR(255) NOT NULL,\n  updated_at VARCHAR(255) NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE user_puzzle_session ADD FOREIGN KEY (session_id) REFERENCES session (id);\nALTER TABLE user_puzzle_session ADD FOREIGN KEY (user_id) REFERENCES user (id);\n\n-- puzzle_result table\nCREATE TABLE puzzle_result (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  puzzle_id VARCHAR(255) NOT NULL,\n  is_correct BOOLEAN NOT NULL,\n  time_spent INTEGER NOT NULL,\n  hints_used INTEGER NOT NULL,\n  attempts INTEGER NOT NULL,\n  rating INTEGER NOT NULL,\n  theme VARCHAR(255) NOT NULL,\n  difficulty VARCHAR(255) NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE puzzle_result ADD FOREIGN KEY (puzzle_id) REFERENCES puzzle (id);\n\n-- puzzle_session table\nCREATE TABLE puzzle_session (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  session_id VARCHAR(255) NOT NULL,\n  date VARCHAR(255) NOT NULL,\n  puzzles_solved INTEGER NOT NULL,\n  correct_answers INTEGER NOT NULL,\n  total_time INTEGER NOT NULL,\n  average_rating INTEGER NOT NULL,\n  themes TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE puzzle_session ADD FOREIGN KEY (session_id) REFERENCES session (id);\n\n-- custom_puzzle table\nCREATE TABLE custom_puzzle (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  fen VARCHAR(255) NOT NULL,\n  solution TEXT NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  theme VARCHAR(255) NOT NULL,\n  difficulty TEXT NOT NULL,\n  rating INTEGER NOT NULL,\n  moves INTEGER NOT NULL,\n  tags TEXT NOT NULL,\n  source TEXT NOT NULL,\n  author TEXT NOT NULL,\n  created_at TEXT NOT NULL,\n  updated_at TEXT NOT NULL,\n  attempt_count INTEGER NOT NULL,\n  success_rate INTEGER NOT NULL,\n  average_time INTEGER NOT NULL,\n  collection_id VARCHAR(255),\n  hint1 VARCHAR(255) NOT NULL,\n  hint2 VARCHAR(255) NOT NULL,\n  hint3 VARCHAR(255) NOT NULL,\n  notes VARCHAR(255),\n  is_featured BOOLEAN NOT NULL,\n  is_bookmarked BOOLEAN NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE custom_puzzle ADD FOREIGN KEY (collection_id) REFERENCES collection (id);\n\n-- custom_puzzle_collection table\nCREATE TABLE custom_puzzle_collection (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  visibility TEXT NOT NULL,\n  puzzle_ids TEXT NOT NULL,\n  author TEXT NOT NULL,\n  tags TEXT NOT NULL,\n  created_at TEXT NOT NULL,\n  updated_at TEXT NOT NULL,\n  access_count INTEGER NOT NULL,\n  average_rating INTEGER NOT NULL,\n  thumbnail VARCHAR(255),\n  is_featured BOOLEAN NOT NULL,\n  is_bookmarked BOOLEAN NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- custom_puzzle_session table\nCREATE TABLE custom_puzzle_session (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  current_puzzle_index INTEGER NOT NULL,\n  board_position VARCHAR(255) NOT NULL,\n  move_count INTEGER NOT NULL,\n  hints_used INTEGER NOT NULL,\n  status TEXT NOT NULL,\n  show_hint BOOLEAN NOT NULL,\n  time_elapsed INTEGER NOT NULL,\n  is_timer_active BOOLEAN NOT NULL,\n  user_moves TEXT NOT NULL,\n  active_tab TEXT NOT NULL,\n  current_collection TEXT,\n  filters TEXT NOT NULL,\n  search_query VARCHAR(255) NOT NULL,\n  sort_by TEXT NOT NULL,\n  sort_order TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- custom_puzzle_board_props table\nCREATE TABLE custom_puzzle_board_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  position VARCHAR(255) NOT NULL,\n  on_piece_drop TEXT NOT NULL,\n  orientation TEXT,\n  show_coordinates BOOLEAN,\n  board_theme TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- custom_puzzle_controls_props table\nCREATE TABLE custom_puzzle_controls_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  current_puzzle_index INTEGER NOT NULL,\n  total_puzzles INTEGER NOT NULL,\n  can_go_previous BOOLEAN NOT NULL,\n  can_go_next BOOLEAN NOT NULL,\n  on_previous TEXT NOT NULL,\n  on_next TEXT NOT NULL,\n  on_reset TEXT NOT NULL,\n  on_skip TEXT NOT NULL,\n  on_bookmark TEXT NOT NULL,\n  on_share TEXT NOT NULL,\n  is_bookmarked BOOLEAN NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- custom_puzzle_info_props table\nCREATE TABLE custom_puzzle_info_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  puzzle TEXT NOT NULL,\n  session TEXT NOT NULL,\n  on_request_hint TEXT NOT NULL,\n  get_current_hint TEXT NOT NULL,\n  format_time TEXT NOT NULL,\n  on_edit TEXT,\n  on_delete TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- custom_puzzle_collection_browser_props table\nCREATE TABLE custom_puzzle_collection_browser_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  collections TEXT NOT NULL,\n  user_collections TEXT NOT NULL,\n  on_select_collection TEXT NOT NULL,\n  on_create_collection TEXT NOT NULL,\n  on_import_collection TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- puzzle_import_export_props table\nCREATE TABLE puzzle_import_export_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  on_import_p_g_n TEXT NOT NULL,\n  on_import_from_u_r_l TEXT NOT NULL,\n  on_export_collection TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  import_progress TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- puzzle_sharing_props table\nCREATE TABLE puzzle_sharing_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  puzzle TEXT NOT NULL,\n  on_generate_share_link TEXT NOT NULL,\n  on_copy_to_clipboard TEXT NOT NULL,\n  on_share_to_social TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- custom_move_validation_result table\nCREATE TABLE custom_move_validation_result (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  is_valid BOOLEAN NOT NULL,\n  is_correct BOOLEAN NOT NULL,\n  is_complete BOOLEAN NOT NULL,\n  move TEXT,\n  error VARCHAR(255),\n  feedback VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- custom_puzzle_filters table\nCREATE TABLE custom_puzzle_filters (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  difficulty TEXT,\n  themes TEXT,\n  rating INTEGER,\n  source TEXT,\n  tags TEXT,\n  collections TEXT,\n  author VARCHAR(255),\n  date_range TEXT,\n  min_success_rate INTEGER,\n  bookmarked_only BOOLEAN,\n  featured_only BOOLEAN,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- custom_puzzle_search_result table\nCREATE TABLE custom_puzzle_search_result (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  puzzles TEXT NOT NULL,\n  total_count INTEGER NOT NULL,\n  current_page INTEGER NOT NULL,\n  total_pages INTEGER NOT NULL,\n  applied_filters TEXT NOT NULL,\n  search_query VARCHAR(255) NOT NULL,\n  execution_time INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- custom_puzzle_form_data table\nCREATE TABLE custom_puzzle_form_data (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  fen VARCHAR(255) NOT NULL,\n  solution TEXT NOT NULL,\n  theme VARCHAR(255) NOT NULL,\n  difficulty TEXT NOT NULL,\n  tags TEXT NOT NULL,\n  hint1 VARCHAR(255) NOT NULL,\n  hint2 VARCHAR(255) NOT NULL,\n  hint3 VARCHAR(255) NOT NULL,\n  notes VARCHAR(255),\n  collection_id VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE custom_puzzle_form_data ADD FOREIGN KEY (collection_id) REFERENCES collection (id);\n\n-- endgame_category_info table\nCREATE TABLE endgame_category_info (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  name TEXT NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  count INTEGER NOT NULL,\n  icon VARCHAR(255) NOT NULL,\n  color VARCHAR(255) NOT NULL,\n  difficulty_range TEXT NOT NULL,\n  total_study_time INTEGER NOT NULL,\n  is_unlocked BOOLEAN NOT NULL,\n  progress INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- endgame_categories_props table\nCREATE TABLE endgame_categories_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  categories TEXT NOT NULL,\n  selected_category TEXT NOT NULL,\n  on_category_select TEXT NOT NULL,\n  search_filter VARCHAR(255) NOT NULL,\n  on_search_change TEXT NOT NULL,\n  progress TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- endgame_library_filters table\nCREATE TABLE endgame_library_filters (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  category TEXT,\n  difficulty_range TEXT,\n  study_time_range TEXT,\n  win_rate_range TEXT,\n  include_tags TEXT,\n  exclude_tags TEXT,\n  unlocked_only BOOLEAN,\n  studied_only BOOLEAN,\n  search_text VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- search_interface_props table\nCREATE TABLE search_interface_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  query VARCHAR(255) NOT NULL,\n  results TEXT NOT NULL,\n  filters TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  suggestions TEXT NOT NULL,\n  on_query_change TEXT NOT NULL,\n  on_filters_change TEXT NOT NULL,\n  on_suggestion_select TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- opening_puzzle table\nCREATE TABLE opening_puzzle (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id INTEGER NOT NULL,\n  fen VARCHAR(255) NOT NULL,\n  solution TEXT NOT NULL,\n  opening VARCHAR(255) NOT NULL,\n  eco VARCHAR(255) NOT NULL,\n  theme VARCHAR(255) NOT NULL,\n  difficulty TEXT NOT NULL,\n  rating INTEGER NOT NULL,\n  moves INTEGER NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  theory VARCHAR(255) NOT NULL,\n  trap VARCHAR(255) NOT NULL,\n  hint1 VARCHAR(255) NOT NULL,\n  hint2 VARCHAR(255) NOT NULL,\n  hint3 VARCHAR(255) NOT NULL,\n  prevention VARCHAR(255) NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- puzzle_session table\nCREATE TABLE puzzle_session (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  current_puzzle_index INTEGER NOT NULL,\n  board_position VARCHAR(255) NOT NULL,\n  move_count INTEGER NOT NULL,\n  hints_used INTEGER NOT NULL,\n  status TEXT NOT NULL,\n  show_hint BOOLEAN NOT NULL,\n  time_elapsed INTEGER NOT NULL,\n  is_timer_active BOOLEAN NOT NULL,\n  user_moves TEXT NOT NULL,\n  active_tab TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- puzzle_board_props table\nCREATE TABLE puzzle_board_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  position VARCHAR(255) NOT NULL,\n  on_piece_drop TEXT NOT NULL,\n  orientation TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- puzzle_controls_props table\nCREATE TABLE puzzle_controls_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  current_puzzle_index INTEGER NOT NULL,\n  total_puzzles INTEGER NOT NULL,\n  can_go_previous BOOLEAN NOT NULL,\n  can_go_next BOOLEAN NOT NULL,\n  on_previous TEXT NOT NULL,\n  on_next TEXT NOT NULL,\n  on_reset TEXT NOT NULL,\n  on_skip TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- puzzle_info_props table\nCREATE TABLE puzzle_info_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  puzzle TEXT NOT NULL,\n  session TEXT NOT NULL,\n  on_request_hint TEXT NOT NULL,\n  get_current_hint TEXT NOT NULL,\n  format_time TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- puzzle_tabs_props table\nCREATE TABLE puzzle_tabs_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  puzzle TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- puzzle_progress_props table\nCREATE TABLE puzzle_progress_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  current_puzzle_index INTEGER NOT NULL,\n  total_puzzles INTEGER NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- puzzle_category table\nCREATE TABLE puzzle_category (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  icon VARCHAR(255) NOT NULL,\n  route VARCHAR(255) NOT NULL,\n  difficulty TEXT NOT NULL,\n  total_puzzles INTEGER NOT NULL,\n  completed_puzzles INTEGER NOT NULL,\n  average_rating INTEGER NOT NULL,\n  personal_best INTEGER NOT NULL,\n  last_played TEXT,\n  achievements TEXT NOT NULL,\n  color VARCHAR(255) NOT NULL,\n  gradient VARCHAR(255) NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- puzzle_difficulty table\nCREATE TABLE puzzle_difficulty (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  level TEXT NOT NULL,\n  rating INTEGER NOT NULL,\n  puzzle_count INTEGER NOT NULL,\n  completed INTEGER NOT NULL,\n  accuracy INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- recent_puzzle table\nCREATE TABLE recent_puzzle (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  category VARCHAR(255) NOT NULL,\n  difficulty VARCHAR(255) NOT NULL,\n  rating INTEGER NOT NULL,\n  completed BOOLEAN NOT NULL,\n  accuracy INTEGER,\n  time_spent INTEGER,\n  date TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- puzzle_selection_filters table\nCREATE TABLE puzzle_selection_filters (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  difficulty TEXT NOT NULL,\n  categories TEXT NOT NULL,\n  show_completed BOOLEAN NOT NULL,\n  sort_by TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- category_card_props table\nCREATE TABLE category_card_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  category TEXT NOT NULL,\n  on_click TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- recent_puzzles_props table\nCREATE TABLE recent_puzzles_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  puzzles TEXT NOT NULL,\n  on_puzzle_click TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- ========================================
