-- analysis_settings table\nCREATE TABLE analysis_settings (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  depth INTEGER NOT NULL,\n  multi_p_v INTEGER NOT NULL,\n  time_limit INTEGER,\n  threads INTEGER,\n  hash_size INTEGER,\n  contempt INTEGER,\n  PRIMARY KEY (id)\n);\n\n-- engine_status table\nCREATE TABLE engine_status (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  engine_name VARCHAR(255) NOT NULL,\n  version VARCHAR(255) NOT NULL,\n  is_analyzing BOOLEAN NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- analysis_settings table\nCREATE TABLE analysis_settings (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  depth INTEGER NOT NULL,\n  multi_p_v INTEGER NOT NULL,\n  time_limit INTEGER,\n  threads INTEGER,\n  hash_size INTEGER,\n  contempt INTEGER,\n  PRIMARY KEY (id)\n);\n\n-- engine_status table\nCREATE TABLE engine_status (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  engine_name VARCHAR(255) NOT NULL,\n  version VARCHAR(255) NOT NULL,\n  is_analyzing BOOLEAN NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- predefined_position table\nCREATE TABLE predefined_position (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  name VARCHAR(255) NOT NULL,\n  fen VARCHAR(255) NOT NULL,\n  icon TEXT NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  category TEXT NOT NULL,\n  difficulty TEXT NOT NULL,\n  tags TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- game_filter table\nCREATE TABLE game_filter (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  source TEXT,\n  result TEXT,\n  opponent TEXT,\n  date_range TEXT,\n  min_accuracy INTEGER,\n  max_accuracy INTEGER,\n  openings TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- engine_analysis table\nCREATE TABLE engine_analysis (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  depth INTEGER NOT NULL,\n  eval INTEGER NOT NULL,\n  pv TEXT NOT NULL,\n  nodes INTEGER NOT NULL,\n  time INTEGER NOT NULL,\n  nps INTEGER NOT NULL,\n  mate INTEGER,\n  multipv INTEGER,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- analysis_position table\nCREATE TABLE analysis_position (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  name VARCHAR(255) NOT NULL,\n  fen VARCHAR(255) NOT NULL,\n  category TEXT NOT NULL,\n  rating INTEGER NOT NULL,\n  description VARCHAR(255),\n  tags TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- move_tree_node table\nCREATE TABLE move_tree_node (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  move VARCHAR(255) NOT NULL,\n  san VARCHAR(255) NOT NULL,\n  fen VARCHAR(255) NOT NULL,\n  eval INTEGER,\n  comment VARCHAR(255),\n  variations TEXT,\n  children TEXT,\n  parent TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- analysis_settings table\nCREATE TABLE analysis_settings (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  depth INTEGER NOT NULL,\n  multi_p_v INTEGER NOT NULL,\n  threads INTEGER NOT NULL,\n  hash_size INTEGER NOT NULL,\n  time_limit INTEGER,\n  contempt INTEGER,\n  PRIMARY KEY (id)\n);\n\n-- engine_status table\nCREATE TABLE engine_status (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  is_running BOOLEAN NOT NULL,\n  engine_name VARCHAR(255) NOT NULL,\n  version VARCHAR(255) NOT NULL,\n  is_analyzing BOOLEAN NOT NULL,\n  current_depth INTEGER NOT NULL,\n  current_nodes INTEGER NOT NULL,\