LT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- engine_line_props table\nCREATE TABLE engine_line_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  analysis TEXT NOT NULL,\n  index INTEGER NOT NULL,\n  on_play_line TEXT,\n  class_name VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- position_setup_props table\nCREATE TABLE position_setup_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  current_fen VARCHAR(255) NOT NULL,\n  on_load_fen TEXT NOT NULL,\n  on_reset_position TEXT NOT NULL,\n  class_name VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- move_navigation_props table\nCREATE TABLE move_navigation_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  game_history TEXT NOT NULL,\n  current_move_index INTEGER NOT NULL,\n  on_go_to_move TEXT NOT NULL,\n  on_undo TEXT NOT NULL,\n  on_redo TEXT NOT NULL,\n  class_name VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- analysis_controls_props table\nCREATE TABLE analysis_controls_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  analysis_mode TEXT NOT NULL,\n  is_analyzing BOOLEAN NOT NULL,\n  engine_status TEXT NOT NULL,\n  analysis_settings TEXT NOT NULL,\n  on_start_analysis TEXT NOT NULL,\n  on_stop_analysis TEXT NOT NULL,\n  on_mode_change TEXT NOT NULL,\n  on_settings_change TEXT NOT NULL,\n  class_name VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- position_database_props table\nCREATE TABLE position_database_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  positions TEXT NOT NULL,\n  on_load_position TEXT NOT NULL,\