s table\nCREATE TABLE tablebase_query_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  position VARCHAR(255) NOT NULL,\n  on_query TEXT NOT NULL,\n  result TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  history TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- endgame_analysis_props table\nCREATE TABLE endgame_analysis_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  position TEXT NOT NULL,\n  analysis TEXT NOT NULL,\n  is_analyzing BOOLEAN NOT NULL,\n  on_analyze TEXT NOT NULL,\n  on_analyze_variation TEXT NOT NULL,\n  engine_depth INTEGER NOT NULL,\n  on_depth_change TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- endgame_practice_props table\nCREATE TABLE endgame_practice_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  position TEXT NOT NULL,\n  session TEXT NOT NULL,\n  practice_types TEXT NOT NULL,\n  on_start_practice TEXT NOT NULL,\n  on_end_practice TEXT NOT NULL,\n  on_move TEXT NOT NULL,\n  progress TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- endgame_library_hook_return table\nCREATE TABLE endgame_library_hook_return (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  categories TEXT NOT NULL,\n  positions TEXT NOT NULL,\n  filtered_positions TEXT NOT NULL,\n  selected_category TEXT NOT NULL,\n  selected_position TEXT NOT NULL,\n  compositions TEXT NOT NULL,\n  active_tab TEXT NOT NULL,\n  search_filter VARCHAR(255) NOT NULL,\n  sort_by TEXT NOT NULL,\n  sort_order TEXT NOT NULL,\n  current_analysis TEXT NOT NULL,\n  is_analyzing BOOLEAN NOT NULL,\n  tablebase_result TEXT NOT NULL,\n  is_querying BOOLEAN NOT 