,\n  time_grade TEXT NOT NULL,\n  time_blunders TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- performance_metrics table\nCREATE TABLE performance_metrics (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  overall_accuracy INTEGER NOT NULL,\n  phase_accuracy TEXT NOT NULL,\n  move_classifications TEXT NOT NULL,\n  performance_rating INTEGER NOT NULL,\n  average_centipawn_loss INTEGER NOT NULL,\n  blunder_rate INTEGER NOT NULL,\n  time_efficiency INTEGER NOT NULL,\n  critical_position_score INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- game_review table\nCREATE TABLE game_review (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  game_info TEXT NOT NULL,\n  pgn VARCHAR(255) NOT NULL,\n  source TEXT NOT NULL,\n  analysis_config TEXT NOT NULL,\n  analysis_status TEXT NOT NULL,\n  analysis_progress INTEGER NOT NULL,\n  moves TEXT NOT NULL,\n  opening TEXT NOT NULL,\n  endgame TEXT,\n  time_analysis TEXT NOT NULL,\n  performance TEXT NOT NULL,\n  key_positions TEXT NOT NULL,\n  summary TEXT NOT NULL,\n  improvements TEXT NOT NULL,\n  created_at INTEGER NOT NULL,\n  analysis_completed_at INTEGER,\n  last_viewed_at INTEGER NOT NULL,\n  user_notes TEXT NOT NULL,\n  bookmarks TEXT NOT NULL,\n  export_settings TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- game_import table\nCREATE TABLE game_import (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  source TEXT NOT NULL,\n  game_data VARCHAR(255) NOT NULL,\n  imported_at INTEGER NOT NULL,\n  metadata TEXT NOT NULL,\n  validation TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- review_session table\nCREATE TABLE review_session (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  current_game TEXT NOT NULL,\n  current_move_index INTEGER NOT NULL,\n  board_orientation TEXT NOT NULL,\n  view_mode TEXT NOT NULL,\n  display_settings TEXT NOT NULL,\n  filters TEXT NOT NULL,\n  comparison_game TEXT,\n  training_mode TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- game_collection table\nCREATE TABLE game_collection (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  game_ids TEXT NOT NULL,\n  tags TEXT NOT NULL,\n  created_at INTEGER NOT NULL,\n  updated_at INTEGER NOT NULL,\n  stats TEXT NOT NULL,\n  sharing TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- game_selection_props table\nCREATE TABLE game_selection_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  games TEXT NOT NULL,\n  selected_game TEXT NOT NULL,\n  on_game_select TEXT NOT NULL,\n  on_import_game TEXT NOT NULL,\n  search_query VARCHAR(255) NOT NULL,\n  on_search_change TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- move_analysis_props table\nCREATE TABLE move_analysis_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  current_move TEXT NOT NULL,\n  all_moves TEXT NOT NULL,\n  current_index INTEGER NOT NULL,\n  on_move_select TEXT NOT NULL,\n  show_engine_lines BOOLEAN NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- engine_evaluation_props table\nCREATE TABLE engine_evaluation_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  evaluation INTEGER NOT NULL,\n  best_moves TEXT NOT NULL,\n  move_classification TEXT,\n  is_analyzing BOOLEAN NOT NULL,\n  depth INTEGER NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- game_statistics_props table\nCREATE TABLE game_statistics_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  performance TEXT NOT NULL,\n  time_analysis TEXT NOT NULL,\n  key_positions TEXT NOT NULL,\n  player_color TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- game_review_hook_return table\nCREATE TABLE game_review_hook_return (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  current_game TEXT NOT NULL,\n  review_session TEXT NOT NULL,\n  available_games TEXT NOT NULL,\n  game_collections TEXT NOT NULL,\n  import_state TEXT NOT NULL,\n  analysis_state TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  select_game TEXT NOT NULL,\n  import_game TEXT NOT NULL,\n  analyze_game TEXT NOT NULL,\n  navigate_to_move TEXT NOT NULL,\n  update_display_settings TEXT NOT NULL,\n  update_filters TEXT NOT NULL,\n  save_user_note TEXT NOT NULL,\n  bookmark_position TEXT NOT NULL,\n  export_game TEXT NOT NULL,\n  create_collection TEXT NOT NULL,\n  delete_game TEXT NOT NULL,\n  can_navigate_back BOOLEAN NOT NULL,\n  can_navigate_forward BOOLEAN NOT NULL,\n  current_move_index INTEGER NOT NULL,\n  total_moves INTEGER NOT NULL,\n  error VARCHAR(255) NOT NULL,\n  clear_error TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- game_review_service table\nCREATE TABLE game_review_service (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  import_from_p_g_n TEXT NOT NULL,\n  import_from_chess_com TEXT NOT NULL,\n  import_from_lichess TEXT NOT NULL,\n  analyze_game TEXT NOT NULL,\n  export_game TEXT NOT NULL,\n  save_review TEXT NOT NULL,\n  load_reviews TEXT NOT NULL,\n  delete_review TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- search_analysis table\nCREATE TABLE search_analysis (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  intent TEXT NOT NULL,\n  suggested_types TEXT NOT NULL,\n  suggested_categories TEXT NOT NULL,\n  complexity TEXT NOT NULL,\n  keywords TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- master_player table\nCREATE TABLE master_player (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  name VARCHAR(255) NOT NULL,\n  rating INTEGER NOT NULL,\n  peak_rating INTEGER,\n  country VARCHAR(255),\n  birth_year INTEGER,\n  titles TEXT NOT NULL,\n  championship_years TEXT,\n  biography VARCHAR(255),\n  playing_style VARCHAR(255),\n  specialties TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- tournament table\nCREATE TABLE tournament (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  name VARCHAR(255) NOT NULL,\n  location VARCHAR(255) NOT NULL,\n  year INTEGER NOT NULL,\n  date VARCHAR(255),\n  type TEXT NOT NULL,\n  time_control TEXT NOT NULL,\n  player_count INTEGER,\n  prize_fund VARCHAR(255),\n  significance VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- move_annotation table\nCREATE TABLE move_annotation (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  move_number INTEGER NOT NULL,\n  san VARCHAR(255) NOT NULL,\n  comment VARCHAR(255) NOT NULL,\n  assessment TEXT,\n  evaluation INTEGER,\n  is_key_moment BOOLEAN NOT NULL,\n  themes TEXT,\n  alternatives TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- game_analysis table\nCREATE TABLE game_analysis (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  quality INTEGER NOT NULL,\n  phases TEXT NOT NULL,\n  strategic_themes TEXT NOT NULL,\n  tactical_themes TEXT NOT NULL,\n  educational_value INTEGER NOT NULL,\n  learning_objectives TEXT NOT NULL,\n  study_recommendations TEXT NOT NULL,\n  historical_significance VARCHAR(255),\n  quotes TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- master_game table\nCREATE TABLE master_game (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  white TEXT NOT NULL,\n  black TEXT NOT NULL,\n  tournament TEXT NOT NULL,\n  result TEXT NOT NULL,\n  opening TEXT NOT NULL,\n  pgn VARCHAR(255) NOT NULL,\n  annotations TEXT NOT NULL,\n  key_moments TEXT NOT NULL,\n  analysis TEXT NOT NULL,\n  move_count INTEGER NOT NULL,\n  duration VARCHAR(255),\n  final_position VARCHAR(255),\n  is_bookmarked BOOLEAN NOT NULL,\n  personal_notes VARCHAR(255),\n  study_progress TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- game_filters table\nCREATE TABLE game_filters (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  search_term VARCHAR(255) NOT NULL,\n  players TEXT NOT NULL,\n  tournament_types TEXT NOT NULL,\n  opening_categories TEXT NOT NULL,\n  eco_codes TEXT NOT NULL,\n  results TEXT NOT NULL,\n  year_range TEXT NOT NULL,\n  rating_range INTEGER NOT NULL,\n  quality_range TEXT NOT NULL,\n  themes TEXT NOT NULL,\n  bookmarked_only BOOLEAN NOT NULL,\n  sort_by TEXT NOT NULL,\n  sort_order TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- library_stats table\nCREATE TABLE library_stats (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  total_games INTEGER NOT NULL,\n  games_by_century TEXT NOT NULL,\n  games_by_opening TEXT NOT NULL,\n  games_by_result TEXT NOT NULL,\n  average_rating INTEGER NOT NULL,\n  top_players TEXT NOT NULL,\n  most_studied TEXT NOT NULL,\n  theme_distribution TEXT NOT NULL,\n  user_stats TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- study_session table\nCREATE TABLE study_session (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  game_id VARCHAR(255) NOT NULL,\n  start_time INTEGER NOT NULL,\n  end_time INTEGER,\n  moves_studied TEXT NOT NULL,\n  time_per_move TEXT NOT NULL,\n  analysis_attempts TEXT NOT NULL,\n  notes VARCHAR(255) NOT NULL,\n  rating INTEGER,\n  concepts_learned TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE study_session ADD FOREIGN KEY (game_id) REFERENCES game (id);\n\n-- master_profile table\nCREATE TABLE master_profile (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  photo_url VARCHAR(255),\n  full_biography VARCHAR(255) NOT NULL,\n  career_highlights TEXT NOT NULL,\n  famous_games TEXT NOT NULL,\n  opening_repertoire TEXT NOT NULL,\n  career_stats TEXT NOT NULL,\n  quotes TEXT NOT NULL,\n  style_analysis TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- game_library_props table\nCREATE TABLE game_library_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  games TEXT NOT NULL,\n  filters TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  selected_game_id VARCHAR(255),\n  on_game_select TEXT NOT NULL,\n  on_filters_change TEXT NOT NULL,\n  on_bookmark_toggle TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE game_library_props ADD FOREIGN KEY (selected_game_id) REFERENCES selected_game (id);\n\n-- game_viewer_props table\nCREATE TABLE game_viewer_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  game TEXT NOT NULL,\n  current_move INTEGER NOT NULL,\n  is_playing BOOLEAN NOT NULL,\n  playback_speed INTEGER NOT NULL,\n  show_coordinates BOOLEAN NOT NULL,\n  show_last_move BOOLEAN NOT NULL,\n  orientation TEXT NOT NULL,\n  on_move_change TEXT NOT NULL,\n  on_play_toggle TEXT NOT NULL,\n  on_speed_change TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- master_analysis_props table\nCREATE TABLE master_analysis_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  game TEXT NOT NULL,\n  current_move INTEGER NOT NULL,\n  mode TEXT NOT NULL,\n  on_mode_change TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- player_profile_props table\nCREATE TABLE player_profile_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  player TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  on_view_games TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- master_games_hook_return table\nCREATE TABLE master_games_hook_return (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  games TEXT NOT NULL,\n  filtered_games TEXT NOT NULL,\n  selected_game TEXT NOT NULL,\n  current_move INTEGER NOT NULL,\n  library_stats TEXT NOT NULL,\n  filters TEXT NOT NULL,\n  is_playing BOOLEAN NOT NULL,\n  playback_speed INTEGER NOT NULL,\n  board_orientation TEXT NOT NULL,\n  analysis_mode TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  is_loading_game BOOLEAN NOT NULL,\n  select_game TEXT NOT NULL,\n  set_current_move TEXT NOT NULL,\n  toggle_playback TEXT NOT NULL,\n  set_playback_speed TEXT NOT NULL,\n  update_filters TEXT NOT NULL,\n  toggle_bookmark TEXT NOT NULL,\n  flip_board TEXT NOT NULL,\n  set_analysis_mode TEXT NOT NULL,\n  go_to_start TEXT NOT NULL,\n  go_to_end TEXT NOT NULL,\n  go_to_move TEXT NOT NULL,\n  next_move TEXT NOT NULL,\n  previous_move TEXT NOT NULL,\n  start_study_session TEXT NOT NULL,\n  end_study_session TEXT NOT NULL,\n  current_session TEXT NOT NULL,\n  search_games TEXT NOT NULL,\n  get_recommended_games TEXT NOT NULL,\n  get_similar_games TEXT NOT NULL,\n  error VARCHAR(255) NOT NULL,\n  clear_error TEXT NOT NULL,\n  handle_back_click TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- game_search_result table\nCREATE TABLE game_search_result (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  games TEXT NOT NULL,\n  total_count INTEGER NOT NULL,\n  suggestions TEXT,\n  filter_suggestions TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- master_game table\nCREATE TABLE master_game (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  white VARCHAR(255) NOT NULL,\n  black VARCHAR(255) NOT NULL,\n  white_rating INTEGER,\n  black_rating INTEGER,\n  result TEXT NOT NULL,\n  year INTEGER NOT NULL,\n  event VARCHAR(255) NOT NULL,\n  avg_rating INTEGER NOT NULL,\n  moves INTEGER NOT NULL,\n  date VARCHAR(255),\n  round VARCHAR(255),\n  significance VARCHAR(255),\n  game_url VARCHAR(255),\n  pgn VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- position_analysis table\nCREATE TABLE position_analysis (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  position VARCHAR(255) NOT NULL,\n  evaluation INTEGER NOT NULL,\n  evaluation_text VARCHAR(255) NOT NULL,\n  best_moves TEXT NOT NULL,\n  tactical_themes TEXT NOT NULL,\n  pawn_structure TEXT NOT NULL,\n  king_safety TEXT NOT NULL,\n  piece_activity TEXT NOT NULL,\n  space_advantage TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- master_games_props table\nCREATE TABLE master_games_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  opening TEXT NOT NULL,\n  games TEXT NOT NULL,\n  on_game_select TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- move_validation_result table\nCREATE TABLE move_validation_result (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  is_valid BOOLEAN NOT NULL,\n  is_correct BOOLEAN NOT NULL,\n  is_complete BOOLEAN NOT NULL,\n  move TEXT,\n  error VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- game_setup table\nCREATE TABLE game_setup (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  opponent TEXT NOT NULL,\n  player_color TEXT NOT NULL,\n  time_control TEXT NOT NULL,\n  use_opening_book BOOLEAN NOT NULL,\n  show_hints BOOLEAN NOT NULL,\n  enable_sounds BOOLEAN NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- chess_move table\nCREATE TABLE chess_move (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  from VARCHAR(255) NOT NULL,\n  to VARCHAR(255) NOT NULL,\n  piece VARCHAR(255) NOT NULL,\n  captured VARCHAR(255),\n  san VARCHAR(255) NOT NULL,\n  move_number INTEGER NOT NULL,\n  color TEXT NOT NULL,\n  timestamp INTEGER NOT NULL,\n  time_remaining INTEGER NOT NULL,\n  evaluation TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- game_state table\nCREATE TABLE game_state (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  game_id VARCHAR(255) NOT NULL,\n  setup TEXT NOT NULL,\n  position VARCHAR(255) NOT NULL,\n  moves TEXT NOT NULL,\n  status TEXT NOT NULL,\n  result TEXT NOT NULL,\n  current_turn TEXT NOT NULL,\n  time_remaining TEXT NOT NULL,\n  in_check BOOLEAN NOT NULL,\n  legal_moves TEXT NOT NULL,\n  start_time INTEGER NOT NULL,\n  end_time INTEGER,\n  last_move TEXT,\n  ai_thinking BOOLEAN NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE game_state ADD FOREIGN KEY (game_id) REFERENCES game (id);\n\n-- game_analysis table\nCREATE TABLE game_analysis (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  evaluation INTEGER NOT NULL,\n  best_moves TEXT NOT NULL,\n  position_analysis TEXT NOT NULL,\n  tactical_themes TEXT NOT NULL,\n  opening TEXT NOT NULL,\n  endgame TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- game_setup_props table\nCREATE TABLE game_setup_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  setup TEXT NOT NULL,\n  on_setup_change TEXT NOT NULL,\n  on_start_game TEXT NOT NULL,\n  is_valid_setup BOOLEAN NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- chess_game_board_props table\nCREATE TABLE chess_game_board_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  game_state TEXT NOT NULL,\n  on_player_move TEXT NOT NULL,\n  player_color TEXT NOT NULL,\n  show_coordinates BOOLEAN NOT NULL,\n  show_last_move BOOLEAN NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- move_history_props table\nCREATE TABLE move_history_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  moves TEXT NOT NULL,\n  current_move_index INTEGER NOT NULL,\n  on_move_select TEXT NOT NULL,\n  show_evaluations BOOLEAN NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- game_analysis_props table\nCREATE TABLE game_analysis_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  game_state TEXT NOT NULL,\n  analysis TEXT NOT NULL,\n  is_analyzing BOOLEAN NOT NULL,\n  on_analyze TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- play_computer_hook_return table\nCREATE TABLE play_computer_hook_return (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  game_state TEXT NOT NULL,\n  game_analysis TEXT NOT NULL,\n  available_opponents TEXT NOT NULL,\n  performance_stats TEXT NOT NULL,\n  game_setup TEXT NOT NULL,\n  is_valid_setup BOOLEAN NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  is_analyzing BOOLEAN NOT NULL,\n  select_opponent TEXT NOT NULL,\n  update_setup TEXT NOT NULL,\n  start_game TEXT NOT NULL,\n  make_move TEXT NOT NULL,\n  resign_game TEXT NOT NULL,\n  offer_draw TEXT NOT NULL,\n  pause_game TEXT NOT NULL,\n  resume_game TEXT NOT NULL,\n  analyze_position TEXT NOT NULL,\n  can_make_move BOOLEAN NOT NULL,\n  is_player_turn BOOLEAN NOT NULL,\n  game_status TEXT NOT NULL,\n  error VARCHAR(255) NOT NULL,\n  clear_error TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- a_i_move_result table\nCREATE TABLE a_i_move_result (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  move TEXT NOT NULL,\n  confidence INTEGER NOT NULL,\n  calculation_time INTEGER NOT NULL,\n  evaluation INTEGER NOT NULL,\n  depth INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- study_session table\nCREATE TABLE study_session (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  start_time INTEGER NOT NULL,\n  end_time INTEGER NOT NULL,\n  duration INTEGER NOT NULL,\n  content_studied TEXT NOT NULL,\n  xp_earned INTEGER NOT NULL,\n  performance TEXT NOT NULL,\n  notes VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- ========================================
-- LEARNING DOMAIN
-- ========================================

-- related_tutorial table\nCREATE TABLE related_tutorial (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  duration VARCHAR(255) NOT NULL,\n  thumbnail VARCHAR(255) NOT NULL,\n  category VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- user_study_plan table\nCREATE TABLE user_study_plan (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  user_id VARCHAR(255) NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  goals TEXT NOT NULL,\n  target_rating INTEGER NOT NULL,\n  estimated_weeks INTEGER NOT NULL,\n  is_active BOOLEAN NOT NULL,\n  progress TEXT NOT NULL,\n  modules TEXT NOT NULL,\n  created_at VARCHAR(255) NOT NULL,\n  updated_at VARCHAR(255) NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE user_study_plan ADD FOREIGN KEY (user_id) REFERENCES user (id);\n\n-- study_module table\nCREATE TABLE study_module (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  estimated_hours INTEGER NOT NULL,\n  is_completed BOOLEAN NOT NULL,\n  completed_at VARCHAR(255),\n  topics TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- study_topic table\nCREATE TABLE study_topic (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  type TEXT NOT NULL,\n  is_completed BOOLEAN NOT NULL,\n  completed_at VARCHAR(255),\n  notes VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- progress_tracker_props table\nCREATE TABLE progress_tracker_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  progress INTEGER NOT NULL,\n  target INTEGER NOT NULL,\n  label VARCHAR(255) NOT NULL,\n  theme TEXT NOT NULL,\n  size TEXT,\n  show_percentage BOOLEAN,\n  animated BOOLEAN,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- study_progress table\nCREATE TABLE study_progress (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  position_id VARCHAR(255) NOT NULL,\n  sessions_completed INTEGER NOT NULL,\n  total_study_time INTEGER NOT NULL,\n  mastery_level INTEGER NOT NULL,\n  last_studied INTEGER NOT NULL,\n  practice_stats TEXT NOT NULL,\n  moves_practiced TEXT NOT NULL,\n  variations_mastered TEXT NOT NULL,\n  notes VARCHAR(255) NOT NULL,\n  is_bookmarked BOOLEAN NOT NULL,\n  rating INTEGER,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE study_progress ADD FOREIGN KEY (position_id) REFERENCES position (id);\n\n-- tutorial_step table\nCREATE TABLE tutorial_step (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  step_number INTEGER NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  instructions VARCHAR(255) NOT NULL,\n  visual_aid TEXT,\n  interaction TEXT,\n  tips TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- tutorial table\nCREATE TABLE tutorial (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  category TEXT NOT NULL,\n  difficulty TEXT NOT NULL,\n  steps TEXT NOT NULL,\n  estimated_time INTEGER NOT NULL,\n  prerequisites TEXT,\n  rewards TEXT,\n  metadata TEXT NOT NULL,\n  is_interactive BOOLEAN NOT NULL,\n  thumbnail VARCHAR(255) NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- tutorial_browser_props table\nCREATE TABLE tutorial_browser_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  tutorials TEXT NOT NULL,\n  user_progress TEXT NOT NULL,\n  filter TEXT NOT NULL,\n  on_filter_change TEXT NOT NULL,\n  on_tutorial_start TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- learning_branch table\nCREATE TABLE learning_branch (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  theme VARCHAR(255) NOT NULL,\n  skill_ids TEXT NOT NULL,\n  completion TEXT NOT NULL,\n  difficulty TEXT NOT NULL,\n  estimated_hours INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- learning_recommendation table\nCREATE TABLE learning_recommendation (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  type TEXT NOT NULL,\n  target_skill TEXT NOT NULL,\n  recommended_content TEXT NOT NULL,\n  reasoning VARCHAR(255) NOT NULL,\n  expected_improvement TEXT NOT NULL,\n  priority TEXT NOT NULL,\n  confidence INTEGER NOT NULL,\n  personalization TEXT NOT NULL,\n  expires_at INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- learning_objective table\nCREATE TABLE learning_objective (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  type TEXT NOT NULL,\n  target_skill VARCHAR(255) NOT NULL,\n  criteria TEXT NOT NULL,\n  progress TEXT NOT NULL,\n  study_plan TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- adaptive_difficulty table\nCREATE TABLE adaptive_difficulty (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  current_level TEXT NOT NULL,\n  performance TEXT NOT NULL,\n  adjustment_factors TEXT NOT NULL,\n  recommended_level TEXT NOT NULL,\n  confidence INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- study_session_plan table\nCREATE TABLE study_session_plan (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  planned_start_time INTEGER NOT NULL,\n  estimated_duration INTEGER NOT NULL,\n  intensity TEXT NOT NULL,\n  planned_content TEXT NOT NULL,\n  goals TEXT NOT NULL,\n  prerequisites TEXT NOT NULL,\n  success_metrics TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- weak_area table\nCREATE TABLE weak_area (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  category TEXT NOT NULL,\n  affected_skills TEXT NOT NULL,\n  severity TEXT NOT NULL,\n  analysis TEXT NOT NULL,\n  impact TEXT NOT NULL,\n  improvement_plan TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- learning_milestone table\nCREATE TABLE learning_milestone (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  criteria TEXT NOT NULL,\n  type TEXT NOT NULL,\n  celebration TEXT NOT NULL,\n  status TEXT NOT NULL,\n  achieved_at INTEGER,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- learning_analytics table\nCREATE TABLE learning_analytics (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  period TEXT NOT NULL,\n  trends TEXT NOT NULL,\n  patterns TEXT NOT NULL,\n  achievements TEXT NOT NULL,\n  predictions TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- personalized_learning_path table\nCREATE TABLE personalized_learning_path (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  user_id VARCHAR(255) NOT NULL,\n  created_at INTEGER NOT NULL,\n  last_updated INTEGER NOT NULL,\n  skill_tree TEXT NOT NULL,\n  objectives TEXT NOT NULL,\n  recommendations TEXT NOT NULL,\n  adaptive_difficulty TEXT NOT NULL,\n  planned_sessions TEXT NOT NULL,\n  weak_areas TEXT NOT NULL,\n  milestones TEXT NOT NULL,\n  analytics TEXT NOT NULL,\n  preferences TEXT NOT NULL,\n  progress TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE personalized_learning_path ADD FOREIGN KEY (user_id) REFERENCES user (id);\n\n-- path_viewer_props table\nCREATE TABLE path_viewer_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  learning_path TEXT NOT NULL,\n  current_view TEXT NOT NULL,\n  on_view_change TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- recommendation_engine_props table\nCREATE TABLE recommendation_engine_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  recommendations TEXT NOT NULL,\n  weak_areas TEXT NOT NULL,\n  on_recommendation_accept TEXT NOT NULL,\n  on_recommendation_dismiss TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- learning_analytics_props table\nCREATE TABLE learning_analytics_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  analytics TEXT NOT NULL,\n  selected_period TEXT NOT NULL,\n  on_period_change TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- study_planner_props table\nCREATE TABLE study_planner_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  planned_sessions TEXT NOT NULL,\n  objectives TEXT NOT NULL,\n  on_session_schedule TEXT NOT NULL,\n  on_session_modify TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- milestone_tracker_props table\nCREATE TABLE milestone_tracker_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  milestones TEXT NOT NULL,\n  recent_achievements TEXT NOT NULL,\n  on_milestone_celebrate TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- learning_path_hook_return table\nCREATE TABLE learning_path_hook_return (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  learning_path TEXT NOT NULL,\n  selected_skill TEXT NOT NULL,\n  current_view TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  is_generating_recommendations INTEGER NOT NULL,\n  is_updating_path BOOLEAN NOT NULL,\n  select_skill TEXT NOT NULL,\n  focus_on_skill TEXT NOT NULL,\n  change_view TEXT NOT NULL,\n  accept_recommendation TEXT NOT NULL,\n  dismiss_recommendation TEXT NOT NULL,\n  schedule_study_session TEXT NOT NULL,\n  update_objective TEXT NOT NULL,\n  celebrate_milestone TEXT NOT NULL,\n  get_skill_progress TEXT NOT NULL,\n  get_recommended_next_steps TEXT NOT NULL,\n  get_weakest_areas TEXT NOT NULL,\n  get_predicted_improvement TEXT NOT NULL,\n  refresh_recommendations TEXT NOT NULL,\n  generate_study_plan TEXT NOT NULL,\n  export_progress TEXT NOT NULL,\n  error VARCHAR(255) NOT NULL,\n  clear_error TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- study_session table\nCREATE TABLE study_session (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  game_id VARCHAR(255) NOT NULL,\n  start_time INTEGER NOT NULL,\n  end_time INTEGER,\n  moves_studied TEXT NOT NULL,\n  time_per_move TEXT NOT NULL,\n  analysis_attempts TEXT NOT NULL,\n  notes VARCHAR(255) NOT NULL,\n  rating INTEGER,\n  concepts_learned TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE study_session ADD FOREIGN KEY (game_id) REFERENCES game (id);\n\n-- recommendation_criteria table\nCREATE TABLE recommendation_criteria (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  skill_level TEXT NOT NULL,\n  learning_style TEXT NOT NULL,\n  study_time INTEGER NOT NULL,\n  studied_games TEXT NOT NULL,\n  favorite_openings TEXT NOT NULL,\n  objectives TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- learning_path table\nCREATE TABLE learning_path (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  total_lessons INTEGER NOT NULL,\n  completed_lessons INTEGER NOT NULL,\n  current_lesson INTEGER NOT NULL,\n  estimated_time INTEGER NOT NULL,\n  time_spent INTEGER NOT NULL,\n  difficulty TEXT NOT NULL,\n  category TEXT NOT NULL,\n  progress INTEGER NOT NULL,\n  next_lesson_title VARCHAR(255) NOT NULL,\n  icon TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- study_lesson table\nCREATE TABLE study_lesson (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  type TEXT NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  estimated_time INTEGER NOT NULL,\n  difficulty TEXT NOT NULL,\n  prerequisites TEXT NOT NULL,\n  objectives TEXT NOT NULL,\n  content TEXT NOT NULL,\n  completion TEXT NOT NULL,\n  gamification TEXT NOT NULL,\n  order INTEGER NOT NULL,\n  is_unlocked BOOLEAN NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- lesson_section table\nCREATE TABLE lesson_section (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  type TEXT NOT NULL,\n  content VARCHAR(255) NOT NULL,\n  position VARCHAR(255),\n  resources TEXT,\n  order INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- interactive_element table\nCREATE TABLE interactive_element (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  type TEXT NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  config TEXT NOT NULL,\n  points INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- assessment_question table\nCREATE TABLE assessment_question (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  type TEXT NOT NULL,\n  question VARCHAR(255) NOT NULL,\n  options TEXT,\n  correct_answer TEXT NOT NULL,\n  explanation VARCHAR(255) NOT NULL,\n  points INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- study_module table\nCREATE TABLE study_module (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  category TEXT NOT NULL,\n  difficulty TEXT NOT NULL,\n  estimated_hours INTEGER NOT NULL,\n  icon VARCHAR(255) NOT NULL,\n  lessons TEXT NOT NULL,\n  prerequisites TEXT NOT NULL,\n  learning_outcomes TEXT NOT NULL,\n  completion TEXT NOT NULL,\n  order INTEGER NOT NULL,\n  is_unlocked BOOLEAN NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- learning_path table\nCREATE TABLE learning_path (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  target_level TEXT NOT NULL,\n  category TEXT NOT NULL,\n  thumbnail VARCHAR(255) NOT NULL,\n  total_hours INTEGER NOT NULL,\n  modules TEXT NOT NULL,\n  prerequisites TEXT NOT NULL,\n  completion TEXT NOT NULL,\n  metrics TEXT NOT NULL,\n  is_unlocked BOOLEAN NOT NULL,\n  is_enrolled BOOLEAN NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- study_schedule table\nCREATE TABLE study_schedule (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  frequency TEXT NOT NULL,\n  preferred_times TEXT NOT NULL,\n  days_of_week TEXT NOT NULL,\n  session_duration INTEGER NOT NULL,\n  daily_goal INTEGER NOT NULL,\n  weekly_goal INTEGER NOT NULL,\n  is_active BOOLEAN NOT NULL,\n  next_session TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- achievement_badge table\nCREATE TABLE achievement_badge (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  type TEXT NOT NULL,\n  icon VARCHAR(255) NOT NULL,\n  criteria TEXT NOT NULL,\n  rarity INTEGER NOT NULL,\n  is_earned BOOLEAN NOT NULL,\n  earned_at INTEGER,\n  xp_reward INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- study_progress table\nCREATE TABLE study_progress (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  user_id VARCHAR(255) NOT NULL,\n  total_study_time INTEGER NOT NULL,\n  current_streak INTEGER NOT NULL,\n  longest_streak INTEGER NOT NULL,\n  total_x_p INTEGER NOT NULL,\n  level INTEGER NOT NULL,\n  xp_to_next_level INTEGER NOT NULL,\n  path_progress TEXT NOT NULL,\n  achievements TEXT NOT NULL,\n  stats TEXT NOT NULL,\n  schedule TEXT,\n  recent_sessions TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE study_progress ADD FOREIGN KEY (user_id) REFERENCES user (id);\n\n-- study_session table\nCREATE TABLE study_session (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  start_time INTEGER NOT NULL,\n  end_time INTEGER NOT NULL,\n  duration INTEGER NOT NULL,\n  content_studied TEXT NOT NULL,\n  xp_earned INTEGER NOT NULL,\n  performance TEXT NOT NULL,\n  notes VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- custom_study_plan table\nCREATE TABLE custom_study_plan (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  selected_lessons TEXT NOT NULL,\n  schedule TEXT NOT NULL,\n  goals TEXT NOT NULL,\n  created_at INTEGER NOT NULL,\n  modified_at INTEGER NOT NULL,\n  progress TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- study_recommendation table\nCREATE TABLE study_recommendation (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  type TEXT NOT NULL,\n  content TEXT NOT NULL,\n  reason VARCHAR(255) NOT NULL,\n  priority TEXT NOT NULL,\n  expected_benefit VARCHAR(255) NOT NULL,\n  expires_at INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- plan_overview_props table\nCREATE TABLE plan_overview_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  learning_paths TEXT NOT NULL,\n  progress TEXT NOT NULL,\n  selected_path TEXT NOT NULL,\n  on_path_select TEXT NOT NULL,\n  on_enroll TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- lesson_viewer_props table\nCREATE TABLE lesson_viewer_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  lesson TEXT NOT NULL,\n  on_lesson_complete TEXT NOT NULL,\n  on_next_lesson TEXT NOT NULL,\n  on_prev_lesson TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- progress_tracker_props table\nCREATE TABLE progress_tracker_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  progress TEXT NOT NULL,\n  current_path TEXT NOT NULL,\n  goals TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- study_scheduler_props table\nCREATE TABLE study_scheduler_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  schedule TEXT NOT NULL,\n  on_schedule_update TEXT NOT NULL,\n  recommendations TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- study_plans_hook_return table\nCREATE TABLE study_plans_hook_return (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  learning_paths TEXT NOT NULL,\n  study_progress TEXT NOT NULL,\n  available_badges TEXT NOT NULL,\n  study_schedule TEXT NOT NULL,\n  recommendations TEXT NOT NULL,\n  custom_plans TEXT NOT NULL,\n  selected_path TEXT NOT NULL,\n  current_module TEXT NOT NULL,\n  current_lesson TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  is_lesson_loading BOOLEAN NOT NULL,\n  select_path TEXT NOT NULL,\n  enroll_in_path TEXT NOT NULL,\n  select_module TEXT NOT NULL,\n  select_lesson TEXT NOT NULL,\n  complete_lesson TEXT NOT NULL,\n  update_schedule TEXT NOT NULL,\n  create_custom_plan TEXT NOT NULL,\n  navigate_to_next_lesson TEXT NOT NULL,\n  navigate_to_prev_lesson TEXT NOT NULL,\n  calculate_path_progress TEXT NOT NULL,\n  get_recommended_content TEXT NOT NULL,\n  get_study_streak TEXT NOT NULL,\n  get_todays_goal_progress TEXT NOT NULL,\n  error VARCHAR(255) NOT NULL,\n  clear_error TEXT NOT NULL,\n  handle_tab_change TEXT NOT NULL,\n  handle_lesson_complete TEXT NOT NULL,\n  get_tab_icon TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- study_plans_service table\nCREATE TABLE study_plans_service (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  load_learning_paths TEXT NOT NULL,\n  load_study_progress TEXT NOT NULL,\n  enroll_in_path TEXT NOT NULL,\n  complete_lesson TEXT NOT NULL,\n  update_schedule TEXT NOT NULL,\n  get_recommendations TEXT NOT NULL,\n  create_custom_plan TEXT NOT NULL,\n  record_study_session TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- tutorial_step table\nCREATE TABLE tutorial_step (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  type TEXT NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  instruction VARCHAR(255),\n  estimated_duration INTEGER NOT NULL,\n  is_interactive BOOLEAN NOT NULL,\n  required_actions TEXT,\n  video TEXT,\n  image TEXT,\n  interactive_elements TEXT,\n  quiz TEXT,\n  completion_criteria TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- tutorial table\nCREATE TABLE tutorial (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  summary VARCHAR(255) NOT NULL,\n  category TEXT NOT NULL,\n  difficulty TEXT NOT NULL,\n  estimated_duration INTEGER NOT NULL,\n  steps TEXT NOT NULL,\n  thumbnail_url VARCHAR(255) NOT NULL,\n  tags TEXT NOT NULL,\n  prerequisites TEXT NOT NULL,\n  learning_objectives TEXT NOT NULL,\n  version VARCHAR(255) NOT NULL,\n  created_at INTEGER NOT NULL,\n  updated_at INTEGER NOT NULL,\n  average_rating INTEGER NOT NULL,\n  rating_count INTEGER NOT NULL,\n  completion_rate INTEGER NOT NULL,\n  is_featured BOOLEAN NOT NULL,\n  is_new BOOLEAN NOT NULL,\n  is_recommended BOOLEAN NOT NULL,\n  unlock_requirements TEXT,\n  is_unlocked BOOLEAN NOT NULL,\n  related_tutorials TEXT NOT NULL,\n  type TEXT,\n  instructor TEXT,\n  views INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- tutorial_progress table\nCREATE TABLE tutorial_progress (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  tutorial_id VARCHAR(255) NOT NULL,\n  status TEXT NOT NULL,\n  current_step_index INTEGER NOT NULL,\n  completed_steps TEXT NOT NULL,\n  skipped_steps TEXT NOT NULL,\n  progress_percentage INTEGER NOT NULL,\n  time_spent INTEGER NOT NULL,\n  started_at INTEGER,\n  last_accessed_at INTEGER NOT NULL,\n  completed_at INTEGER,\n  user_rating INTEGER,\n  user_feedback VARCHAR(255),\n  restart_count INTEGER NOT NULL,\n  quiz_scores TEXT,\n  notes VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE tutorial_progress ADD FOREIGN KEY (tutorial_id) REFERENCES tutorial (id);\n\n-- tutorial_achievement table\nCREATE TABLE tutorial_achievement (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  icon VARCHAR(255) NOT NULL,\n  tier TEXT NOT NULL,\n  points INTEGER NOT NULL,\n  requirements TEXT NOT NULL,\n  is_unlocked BOOLEAN NOT NULL,\n  unlocked_at INTEGER,\n  rarity INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- tutorial_filters table\nCREATE TABLE tutorial_filters (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  category TEXT,\n  difficulty TEXT,\n  status TEXT,\n  max_duration INTEGER,\n  tags TEXT,\n  featured_only BOOLEAN,\n  new_only BOOLEAN,\n  recommended_only BOOLEAN,\n  min_rating INTEGER,\n  search_query VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- tutorial_sort_options table\nCREATE TABLE tutorial_sort_options (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  sort_by TEXT NOT NULL,\n  sort_order TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- video_tutorial table\nCREATE TABLE video_tutorial (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  tutorial_id VARCHAR(255) NOT NULL,\n  url VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  thumbnail_url VARCHAR(255) NOT NULL,\n  duration INTEGER NOT NULL,\n  qualities TEXT NOT NULL,\n  subtitles TEXT NOT NULL,\n  chapters TEXT NOT NULL,\n  interactions TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE video_tutorial ADD FOREIGN KEY (tutorial_id) REFERENCES tutorial (id);\n\n-- tutorial_mini_game table\nCREATE TABLE tutorial_mini_game (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  type TEXT NOT NULL,\n  difficulty TEXT NOT NULL,\n  config TEXT NOT NULL,\n  scoring TEXT NOT NULL,\n  instructions TEXT NOT NULL,\n  success_criteria TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- tutorial_statistics table\nCREATE TABLE tutorial_statistics (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  total_tutorials INTEGER NOT NULL,\n  completed_tutorials INTEGER NOT NULL,\n  in_progress_tutorials INTEGER NOT NULL,\n  total_time_spent INTEGER NOT NULL,\n  average_completion_rate INTEGER NOT NULL,\n  favorite_category TEXT NOT NULL,\n  achievements_unlocked INTEGER NOT NULL,\n  total_points INTEGER NOT NULL,\n  learning_streak INTEGER NOT NULL,\n  completion_by_category TEXT NOT NULL,\n  progress_history TEXT NOT NULL,\n  recent_activity TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- tutorial_series table\nCREATE TABLE tutorial_series (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  tutorials TEXT NOT NULL,\n  total_duration VARCHAR(255) NOT NULL,\n  level TEXT NOT NULL,\n  completed INTEGER NOT NULL,\n  total INTEGER NOT NULL,\n  thumbnail VARCHAR(255) NOT NULL,\n  instructor VARCHAR(255) NOT NULL,\n  category TEXT NOT NULL,\n  is_popular BOOLEAN,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- tutorial_recommendation table\nCREATE TABLE tutorial_recommendation (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  tutorial TEXT NOT NULL,\n  score INTEGER NOT NULL,\n  reason TEXT NOT NULL,\n  explanation VARCHAR(255) NOT NULL,\n  confidence TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- tutorial_launcher_props table\nCREATE TABLE tutorial_launcher_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  tutorials TEXT NOT NULL,\n  progress TEXT NOT NULL,\n  filters TEXT NOT NULL,\n  sort_options TEXT NOT NULL,\n  on_launch_tutorial TEXT NOT NULL,\n  on_filters_change TEXT NOT NULL,\n  on_sort_change TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- progress_tracker_props table\nCREATE TABLE progress_tracker_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  statistics TEXT NOT NULL,\n  achievements TEXT NOT NULL,\n  recent_progress TEXT NOT NULL,\n  learning_goals TEXT,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- video_player_props table\nCREATE TABLE video_player_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  video TEXT NOT NULL,\n  current_time INTEGER NOT NULL,\n  player_state TEXT NOT NULL,\n  on_time_update TEXT NOT NULL,\n  on_state_change TEXT NOT NULL,\n  on_chapter_select TEXT NOT NULL,\n  on_interaction_trigger TEXT NOT NULL,\n  show_controls BOOLEAN NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- tutorial_feedback_props table\nCREATE TABLE tutorial_feedback_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  tutorial TEXT NOT NULL,\n  current_rating INTEGER,\n  current_feedback VARCHAR(255),\n  on_submit_rating INTEGER NOT NULL,\n  is_submitting BOOLEAN NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- tutorials_hook_return table\nCREATE TABLE tutorials_hook_return (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  tutorials TEXT NOT NULL,\n  video_tutorials TEXT NOT NULL,\n  mini_games TEXT NOT NULL,\n  quick_start_guides TEXT NOT NULL,\n  progress TEXT NOT NULL,\n  statistics TEXT NOT NULL,\n  achievements TEXT NOT NULL,\n  current_tutorial TEXT NOT NULL,\n  current_tutorial_progress TEXT NOT NULL,\n  is_in_tutorial BOOLEAN NOT NULL,\n  filtered_tutorials TEXT NOT NULL,\n  filters TEXT NOT NULL,\n  sort_options TEXT NOT NULL,\n  search_query VARCHAR(255) NOT NULL,\n  recommendations TEXT NOT NULL,\n  featured_tutorials TEXT NOT NULL,\n  recent_tutorials TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  is_video_loading BOOLEAN NOT NULL,\n  is_progress_saving BOOLEAN NOT NULL,\n  launch_tutorial TEXT NOT NULL,\n  pause_tutorial TEXT NOT NULL,\n  resume_tutorial TEXT NOT NULL,\n  complete_tutorial TEXT NOT NULL,\n  restart_tutorial TEXT NOT NULL,\n  complete_step TEXT NOT NULL,\n  skip_step TEXT NOT NULL,\n  go_to_step TEXT NOT NULL,\n  set_filters TEXT NOT NULL,\n  set_sort_options TEXT NOT NULL,\n  set_search_query TEXT NOT NULL,\n  clear_filters TEXT NOT NULL,\n  update_progress TEXT NOT NULL,\n  save_progress TEXT NOT NULL,\n  play_video TEXT NOT NULL,\n  pause_video TEXT NOT NULL,\n  seek_video TEXT NOT NULL,\n  select_video_chapter TEXT NOT NULL,\n  start_mini_game TEXT NOT NULL,\n  complete_mini_game TEXT NOT NULL,\n  error VARCHAR(255) NOT NULL,\n  clear_error TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- ========================================
-- OPENING DOMAIN
-- ========================================

-- chess_principle table\nCREATE TABLE chess_principle (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  text VARCHAR(255) NOT NULL,\n  category TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- payment_record table\nCREATE TABLE payment_record (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  amount INTEGER NOT NULL,\n  currency VARCHAR(255) NOT NULL,\n  date INTEGER NOT NULL,\n  status TEXT NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  invoice_url VARCHAR(255),\n  receipt_url VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- opening_info table\nCREATE TABLE opening_info (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  name VARCHAR(255) NOT NULL,\n  eco VARCHAR(255) NOT NULL,\n  moves TEXT NOT NULL,\n  popularity INTEGER NOT NULL,\n  win_rate TEXT NOT NULL,\n  games INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- opening_repertoire table\nCREATE TABLE opening_repertoire (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  repertoire_stats TEXT NOT NULL,\n  top_openings TEXT NOT NULL,\n  preparation TEXT NOT NULL,\n  by_color TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- chess_opening table\nCREATE TABLE chess_opening (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  name VARCHAR(255) NOT NULL,\n  eco TEXT NOT NULL,\n  moves TEXT NOT NULL,\n  category VARCHAR(255) NOT NULL,\n  variation VARCHAR(255),\n  characteristics TEXT,\n  themes TEXT,\n  popularity INTEGER,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- opening_filters table\nCREATE TABLE opening_filters (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  search_query VARCHAR(255) NOT NULL,\n  category TEXT NOT NULL,\n  difficulty TEXT NOT NULL,\n  popularity TEXT NOT NULL,\n  min_games INTEGER NOT NULL,\n  rating_range INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- chess_opening table\nCREATE TABLE chess_opening (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  eco TEXT NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  fen VARCHAR(255) NOT NULL,\n  moves TEXT NOT NULL,\n  frequency INTEGER NOT NULL,\n  white_wins INTEGER NOT NULL,\n  draws INTEGER NOT NULL,\n  black_wins INTEGER NOT NULL,\n  avg_rating INTEGER NOT NULL,\n  games INTEGER NOT NULL,\n  category TEXT NOT NULL,\n  difficulty TEXT NOT NULL,\n  popularity TEXT NOT NULL,\n  theory VARCHAR(255) NOT NULL,\n  master_games INTEGER NOT NULL,\n  key_ideas TEXT NOT NULL,\n  aliases TEXT,\n  related_openings TEXT,\n  first_appeared INTEGER,\n  famous_players TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- move_variation table\nCREATE TABLE move_variation (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  move VARCHAR(255) NOT NULL,\n  san VARCHAR(255) NOT NULL,\n  frequency INTEGER NOT NULL,\n  white_wins INTEGER NOT NULL,\n  draws INTEGER NOT NULL,\n  black_wins INTEGER NOT NULL,\n  games INTEGER NOT NULL,\n  eco TEXT NOT NULL,\n  evaluation INTEGER NOT NULL,\n  category TEXT NOT NULL,\n  resulting_fen VARCHAR(255),\n  transpositions TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- opening_tree_node table\nCREATE TABLE opening_tree_node (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  move VARCHAR(255) NOT NULL,\n  fen VARCHAR(255) NOT NULL,\n  move_sequence TEXT NOT NULL,\n  statistics TEXT NOT NULL,\n  variations TEXT NOT NULL,\n  parent TEXT,\n  is_expanded BOOLEAN NOT NULL,\n  eco TEXT,\n  opening_name VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- search_results table\nCREATE TABLE search_results (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  openings TEXT NOT NULL,\n  total_results INTEGER NOT NULL,\n  applied_filters TEXT NOT NULL,\n  search_time INTEGER NOT NULL,\n  suggestions TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- opening_statistics table\nCREATE TABLE opening_statistics (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  total_openings INTEGER NOT NULL,\n  by_category TEXT NOT NULL,\n  by_difficulty TEXT NOT NULL,\n  by_popularity TEXT NOT NULL,\n  most_played TEXT NOT NULL,\n  highest_rated TEXT NOT NULL,\n  recent_additions TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- user_opening_data table\nCREATE TABLE user_opening_data (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  favorites TEXT NOT NULL,\n  recently_studied TEXT NOT NULL,\n  study_progress TEXT NOT NULL,\n  repertoire TEXT NOT NULL,\n  performance TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- opening_search_props table\nCREATE TABLE opening_search_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  filters TEXT NOT NULL,\n  on_filters_change TEXT NOT NULL,\n  results TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- variation_tree_props table\nCREATE TABLE variation_tree_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  current_position VARCHAR(255) NOT NULL,\n  variations TEXT NOT NULL,\n  on_variation_select TEXT NOT NULL,\n  expanded_nodes TEXT NOT NULL,\n  on_node_toggle TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- opening_analysis_props table\nCREATE TABLE opening_analysis_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  position VARCHAR(255) NOT NULL,\n  analysis TEXT NOT NULL,\n  is_analyzing BOOLEAN NOT NULL,\n  on_analyze TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- opening_board_props table\nCREATE TABLE opening_board_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  position VARCHAR(255) NOT NULL,\n  on_move TEXT NOT NULL,\n  allow_moves BOOLEAN NOT NULL,\n  last_move TEXT,\n  arrows TEXT,\n  orientation TEXT NOT NULL,\n  show_coordinates BOOLEAN NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- opening_info_props table\nCREATE TABLE opening_info_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  opening TEXT NOT NULL,\n  current_position VARCHAR(255) NOT NULL,\n  move_sequence TEXT NOT NULL,\n  active_tab TEXT NOT NULL,\n  on_tab_change TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- opening_explorer_hook_return table\nCREATE TABLE opening_explorer_hook_return (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  current_opening TEXT NOT NULL,\n  current_position VARCHAR(255) NOT NULL,\n  move_sequence TEXT NOT NULL,\n  board_orientation TEXT NOT NULL,\n  search_results TEXT NOT NULL,\n  filters TEXT NOT NULL,\n  is_searching BOOLEAN NOT NULL,\n  current_variations TEXT NOT NULL,\n  expanded_nodes TEXT NOT NULL,\n  position_analysis TEXT NOT NULL,\n  is_analyzing BOOLEAN NOT NULL,\n  master_games TEXT NOT NULL,\n  is_loading_games BOOLEAN NOT NULL,\n  active_tab TEXT NOT NULL,\n  select_opening TEXT NOT NULL,\n  make_move TEXT NOT NULL,\n  reset_position TEXT NOT NULL,\n  load_position TEXT NOT NULL,\n  update_filters TEXT NOT NULL,\n  search_openings TEXT NOT NULL,\n  analyze_position TEXT NOT NULL,\n  select_variation TEXT NOT NULL,\n  toggle_node TEXT NOT NULL,\n  set_active_tab TEXT NOT NULL,\n  flip_board TEXT NOT NULL,\n  add_to_favorites TEXT NOT NULL,\n  remove_from_favorites TEXT NOT NULL,\n  is_favorite TEXT NOT NULL,\n  export_position TEXT NOT NULL,\n  copy_f_e_n TEXT NOT NULL,\n  copy_p_g_n TEXT NOT NULL,\n  error VARCHAR(255) NOT NULL,\n  clear_error TEXT NOT NULL,\n  handle_opening_select TEXT NOT NULL,\n  handle_variation_select TEXT NOT NULL,\n  handle_game_select TEXT NOT NULL,\n  opening_stats TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- opening_database_service table\nCREATE TABLE opening_database_service (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  search_openings TEXT NOT NULL,\n  get_opening_by_e_c_o TEXT NOT NULL,\n  get_variations TEXT NOT NULL,\n  get_master_games TEXT NOT NULL,\n  analyze_position TEXT NOT NULL,\n  get_statistics TEXT NOT NULL,\n  get_related_openings TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- a_i_opponent table\nCREATE TABLE a_i_opponent (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  avatar VARCHAR(255) NOT NULL,\n  difficulty TEXT NOT NULL,\n  rating INTEGER NOT NULL,\n  personality TEXT NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  favorite_openings TEXT NOT NULL,\n  specialties TEXT NOT NULL,\n  win_rate INTEGER NOT NULL,\n  backstory VARCHAR(255) NOT NULL,\n  unlock_requirements TEXT,\n  is_unlocked BOOLEAN NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- time_control_config table\nCREATE TABLE time_control_config (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  type TEXT NOT NULL,\n  initial_time INTEGER NOT NULL,\n  increment INTEGER NOT NULL,\n  display_name VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- ========================================
-- PROGRESS DOMAIN
-- ========================================

-- import_progress table\nCREATE TABLE import_progress (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  status TEXT NOT NULL,\n  current INTEGER NOT NULL,\n  total INTEGER NOT NULL,\n  message VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- progress_statistic table\nCREATE TABLE progress_statistic (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  value VARCHAR(255) NOT NULL,\n  label VARCHAR(255) NOT NULL,\n  type TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- user_progress_data table\nCREATE TABLE user_progress_data (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  user_id VARCHAR(255) NOT NULL,\n  current_performance_level TEXT NOT NULL,\n  performance_value INTEGER NOT NULL,\n  progress_metrics TEXT NOT NULL,\n  achievements TEXT NOT NULL,\n  last_activity VARCHAR(255) NOT NULL,\n  progress_history TEXT NOT NULL,\n  created_at VARCHAR(255) NOT NULL,\n  updated_at VARCHAR(255) NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE user_progress_data ADD FOREIGN KEY (user_id) REFERENCES user (id);\n\n-- progress_snapshot table\nCREATE TABLE progress_snapshot (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  date VARCHAR(255) NOT NULL,\n  performance_value INTEGER NOT NULL,\n  tactical_rating INTEGER NOT NULL,\n  puzzles_solved INTEGER NOT NULL,\n  study_streak INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- user_puzzle_stats table\nCREATE TABLE user_puzzle_stats (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  user_id VARCHAR(255) NOT NULL,\n  total_attempts INTEGER NOT NULL,\n  correct_solutions INTEGER NOT NULL,\n  average_rating INTEGER NOT NULL,\n  current_streak INTEGER NOT NULL,\n  longest_streak INTEGER NOT NULL,\n  average_time INTEGER NOT NULL,\n  category_stats TEXT NOT NULL,\n  difficulty_stats TEXT NOT NULL,\n  recent_sessions TEXT NOT NULL,\n  created_at VARCHAR(255) NOT NULL,\n  updated_at VARCHAR(255) NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE user_puzzle_stats ADD FOREIGN KEY (user_id) REFERENCES user (id);\n\n-- achievement_unlock_condition table\nCREATE TABLE achievement_unlock_condition (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  type TEXT NOT NULL,\n  target INTEGER NOT NULL,\n  current INTEGER,\n  description VARCHAR(255) NOT NULL,\n  required_achievements TEXT,\n  time_frame TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- achievement_reward table\nCREATE TABLE achievement_reward (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  xp INTEGER NOT NULL,\n  badge VARCHAR(255),\n  title VARCHAR(255),\n  unlocks TEXT,\n  coins INTEGER,\n  description VARCHAR(255) NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- achievement table\nCREATE TABLE achievement (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  lore VARCHAR(255),\n  icon VARCHAR(255) NOT NULL,\n  category TEXT NOT NULL,\n  rarity TEXT NOT NULL,\n  status TEXT NOT NULL,\n  conditions TEXT NOT NULL,\n  reward TEXT NOT NULL,\n  earned_at TEXT,\n  progress INTEGER NOT NULL,\n  is_hidden BOOLEAN NOT NULL,\n  is_secret BOOLEAN NOT NULL,\n  series VARCHAR(255),\n  series_order INTEGER,\n  tags TEXT NOT NULL,\n  difficulty INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- achievement_series table\nCREATE TABLE achievement_series (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  icon VARCHAR(255) NOT NULL,\n  achievement_ids TEXT NOT NULL,\n  total_count INTEGER NOT NULL,\n  completed_count INTEGER NOT NULL,\n  progress INTEGER NOT NULL,\n  series_reward TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- achievement_stats table\nCREATE TABLE achievement_stats (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  total_achievements INTEGER NOT NULL,\n  completed_achievements INTEGER NOT NULL,\n  completion_rate INTEGER NOT NULL,\n  total_xp_earned INTEGER NOT NULL,\n  by_rarity TEXT NOT NULL,\n  by_category TEXT NOT NULL,\n  recently_earned TEXT NOT NULL,\n  near_completion TEXT NOT NULL,\n  current_streak INTEGER NOT NULL,\n  longest_streak INTEGER NOT NULL,\n  average_difficulty INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- achievement_filters table\nCREATE TABLE achievement_filters (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  categories TEXT NOT NULL,\n  rarities TEXT NOT NULL,\n  statuses TEXT NOT NULL,\n  earned_only BOOLEAN NOT NULL,\n  available_only BOOLEAN NOT NULL,\n  secret_only BOOLEAN NOT NULL,\n  search_text VARCHAR(255) NOT NULL,\n  sort_by TEXT NOT NULL,\n  sort_direction TEXT NOT NULL,\n  difficulty_range TEXT NOT NULL,\n  series_filter VARCHAR(255),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- achievement_share table\nCREATE TABLE achievement_share (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  achievement TEXT NOT NULL,\n  shared_at TEXT NOT NULL,\n  message VARCHAR(255),\n  platform TEXT NOT NULL,\n  reactions INTEGER NOT NULL,\n  comments TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- achievement_leaderboard_entry table\nCREATE TABLE achievement_leaderboard_entry (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  user_id VARCHAR(255) NOT NULL,\n  username VARCHAR(255) NOT NULL,\n  avatar VARCHAR(255),\n  total_achievements INTEGER NOT NULL,\n  completion_rate INTEGER NOT NULL,\n  total_xp INTEGER NOT NULL,\n  rarest_achievement TEXT,\n  latest_achievement TEXT,\n  rank INTEGER NOT NULL,\n  previous_rank INTEGER,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE achievement_leaderboard_entry ADD FOREIGN KEY (user_id) REFERENCES user (id);\n\n-- achievement_notification table\nCREATE TABLE achievement_notification (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  achievement TEXT NOT NULL,\n  earned_at TEXT NOT NULL,\n  is_read BOOLEAN NOT NULL,\n  is_dismissed BOOLEAN NOT NULL,\n  is_animating BOOLEAN,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- achievement_card_props table\nCREATE TABLE achievement_card_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  achievement TEXT NOT NULL,\n  show_progress BOOLEAN,\n  show_details BOOLEAN,\n  on_click TEXT,\n  theme TEXT NOT NULL,\n  size TEXT,\n  variant TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- achievement_grid_props table\nCREATE TABLE achievement_grid_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  achievements TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  filters TEXT NOT NULL,\n  on_filters_change TEXT NOT NULL,\n  on_achievement_click TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  columns INTEGER,\n  show_empty_state BOOLEAN,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- achievement_details_props table\nCREATE TABLE achievement_details_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  achievement TEXT NOT NULL,\n  is_open BOOLEAN NOT NULL,\n  on_close TEXT NOT NULL,\n  on_share TEXT,\n  theme TEXT NOT NULL,\n  series_achievements TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- achievement_filters_props table\nCREATE TABLE achievement_filters_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  filters TEXT NOT NULL,\n  on_filters_change TEXT NOT NULL,\n  available_categories TEXT NOT NULL,\n  available_rarities TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  is_collapsed BOOLEAN,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- achievement_stats_props table\nCREATE TABLE achievement_stats_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  stats TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  show_details BOOLEAN,\n  comparison_stats TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- progress_tracker_props table\nCREATE TABLE progress_tracker_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  progress INTEGER NOT NULL,\n  target INTEGER NOT NULL,\n  label VARCHAR(255) NOT NULL,\n  theme TEXT NOT NULL,\n  size TEXT,\n  show_percentage BOOLEAN,\n  animated BOOLEAN,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- badge_details_props table\nCREATE TABLE badge_details_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  achievement TEXT NOT NULL,\n  size TEXT NOT NULL,\n  show_effects BOOLEAN,\n  theme TEXT NOT NULL,\n  on_click TEXT,\n  is_new BOOLEAN,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- achievements_hook_return table\nCREATE TABLE achievements_hook_return (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  achievements TEXT NOT NULL,\n  filtered_achievements TEXT NOT NULL,\n  achievement_series TEXT NOT NULL,\n  stats TEXT NOT NULL,\n  leaderboard TEXT NOT NULL,\n  notifications TEXT NOT NULL,\n  filters TEXT NOT NULL,\n  set_filters TEXT NOT NULL,\n  reset_filters TEXT NOT NULL,\n  search_achievements TEXT NOT NULL,\n  check_achievement_progress TEXT NOT NULL,\n  share_achievement TEXT NOT NULL,\n  mark_notification_read TEXT NOT NULL,\n  dismiss_notification TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  selected_achievement TEXT NOT NULL,\n  set_selected_achievement TEXT NOT NULL,\n  near_completion_achievements TEXT NOT NULL,\n  recommended_achievements TEXT NOT NULL,\n  error VARCHAR(255) NOT NULL,\n  clear_error TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- achievement_progress_data table\nCREATE TABLE achievement_progress_data (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- performance_metrics table\nCREATE TABLE performance_metrics (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  overall_rating INTEGER NOT NULL,\n  accuracy INTEGER NOT NULL,\n  rating_progression INTEGER NOT NULL,\n  phase_performance TEXT NOT NULL,\n  tactical_performance TEXT NOT NULL,\n  time_management TEXT NOT NULL,\n  evaluation_accuracy TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- trend_analysis table\nCREATE TABLE trend_analysis (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  rating_trends INTEGER NOT NULL,\n  performance_trends TEXT NOT NULL,\n  activity_patterns TEXT NOT NULL,\n  learning_curve TEXT NOT NULL,\n  predictions TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- detailed_statistics table\nCREATE TABLE detailed_statistics (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  user_id VARCHAR(255) NOT NULL,\n  last_updated VARCHAR(255) NOT NULL,\n  analysis_period TEXT NOT NULL,\n  performance TEXT NOT NULL,\n  trends TEXT NOT NULL,\n  openings TEXT NOT NULL,\n  weaknesses TEXT NOT NULL,\n  heat_maps TEXT NOT NULL,\n  comparative TEXT NOT NULL,\n  game_phases TEXT NOT NULL,\n  summary TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE detailed_statistics ADD FOREIGN KEY (user_id) REFERENCES user (id);\n\n-- performance_metrics_props table\nCREATE TABLE performance_metrics_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  metrics TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  time_period TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- detailed_stats_hook_return table\nCREATE TABLE detailed_stats_hook_return (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  statistics TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  error VARCHAR(255) NOT NULL,\n  selected_time_period TEXT NOT NULL,\n  selected_chart_type TEXT NOT NULL,\n  selected_game_phase TEXT NOT NULL,\n  selected_heat_map TEXT NOT NULL,\n  set_time_period TEXT NOT NULL,\n  set_chart_type TEXT NOT NULL,\n  set_game_phase TEXT NOT NULL,\n  set_heat_map TEXT NOT NULL,\n  refresh_data TEXT NOT NULL,\n  export_data TEXT NOT NULL,\n  clear_error TEXT NOT NULL,\n  has_data BOOLEAN NOT NULL,\n  data_quality TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- study_progress table\nCREATE TABLE study_progress (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  position_id VARCHAR(255) NOT NULL,\n  sessions_completed INTEGER NOT NULL,\n  total_study_time INTEGER NOT NULL,\n  mastery_level INTEGER NOT NULL,\n  last_studied INTEGER NOT NULL,\n  practice_stats TEXT NOT NULL,\n  moves_practiced TEXT NOT NULL,\n  variations_mastered TEXT NOT NULL,\n  notes VARCHAR(255) NOT NULL,\n  is_bookmarked BOOLEAN NOT NULL,\n  rating INTEGER,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE study_progress ADD FOREIGN KEY (position_id) REFERENCES position (id);\n\n-- performance_metrics table\nCREATE TABLE performance_metrics (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  overall_accuracy INTEGER NOT NULL,\n  phase_accuracy TEXT NOT NULL,\n  move_classifications TEXT NOT NULL,\n  performance_rating INTEGER NOT NULL,\n  average_centipawn_loss INTEGER NOT NULL,\n  blunder_rate INTEGER NOT NULL,\n  time_efficiency INTEGER NOT NULL,\n  critical_position_score INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- user_progress table\nCREATE TABLE user_progress (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  articles_read TEXT NOT NULL,\n  tutorials_completed TEXT NOT NULL,\n  bookmarks TEXT NOT NULL,\n  recent_searches TEXT NOT NULL,\n  feedback_given TEXT NOT NULL,\n  stats TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- skill_node table\nCREATE TABLE skill_node (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  category TEXT NOT NULL,\n  mastery_level TEXT NOT NULL,\n  mastery_progress INTEGER NOT NULL,\n  prerequisites TEXT NOT NULL,\n  unlocks TEXT NOT NULL,\n  position TEXT NOT NULL,\n  visual TEXT NOT NULL,\n  associated_content TEXT NOT NULL,\n  metrics TEXT NOT NULL,\n  is_unlocked BOOLEAN NOT NULL,\n  is_featured BOOLEAN NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- skill_tree_props table\nCREATE TABLE skill_tree_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  skill_tree TEXT NOT NULL,\n  selected_skill TEXT NOT NULL,\n  on_skill_select TEXT NOT NULL,\n  on_skill_focus TEXT NOT NULL,\n  view_mode TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- performance_stats table\nCREATE TABLE performance_stats (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  games_played INTEGER NOT NULL,\n  games_won INTEGER NOT NULL,\n  games_drawn INTEGER NOT NULL,\n  games_lost INTEGER NOT NULL,\n  win_rate INTEGER NOT NULL,\n  avg_game_length INTEGER NOT NULL,\n  avg_game_duration INTEGER NOT NULL,\n  current_rating INTEGER NOT NULL,\n  peak_rating INTEGER NOT NULL,\n  games_by_difficulty TEXT NOT NULL,\n  time_control_stats TEXT NOT NULL,\n  recent_games TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- opponent_selector_props table\nCREATE TABLE opponent_selector_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  opponents TEXT NOT NULL,\n  selected_opponent TEXT NOT NULL,\n  on_opponent_select TEXT NOT NULL,\n  player_rating INTEGER NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- rating_change table\nCREATE TABLE rating_change (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  old_rating INTEGER NOT NULL,\n  new_rating INTEGER NOT NULL,\n  change INTEGER NOT NULL,\n  reason TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- achievement table\nCREATE TABLE achievement (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  icon VARCHAR(255) NOT NULL,\n  unlocked BOOLEAN NOT NULL,\n  progress INTEGER NOT NULL,\n  total INTEGER NOT NULL,\n  rarity TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- recent_activity table\nCREATE TABLE recent_activity (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  type TEXT NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  time VARCHAR(255) NOT NULL,\n  points VARCHAR(255) NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- stats_grid_props table\nCREATE TABLE stats_grid_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  user_stats TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- stat_card table\nCREATE TABLE stat_card (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  value VARCHAR(255) NOT NULL,\n  change VARCHAR(255) NOT NULL,\n  trend TEXT NOT NULL,\n  icon TEXT NOT NULL,\n  color VARCHAR(255) NOT NULL,\n  subtitle VARCHAR(255),\n  tooltip VARCHAR(255),\n  priority INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- rating_data_point table\nCREATE TABLE rating_data_point (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  date INTEGER NOT NULL,\n  rating INTEGER NOT NULL,\n  label VARCHAR(255),\n  game_type TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- activity_data_point table\nCREATE TABLE activity_data_point (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  date VARCHAR(255) NOT NULL,\n  day VARCHAR(255) NOT NULL,\n  puzzles INTEGER NOT NULL,\n  study_time INTEGER NOT NULL,\n  games INTEGER NOT NULL,\n  total_time INTEGER NOT NULL,\n  quality INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- training_session table\nCREATE TABLE training_session (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  type TEXT NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  duration INTEGER NOT NULL,\n  score INTEGER NOT NULL,\n  timestamp INTEGER NOT NULL,\n  xp_gained INTEGER NOT NULL,\n  accuracy INTEGER,\n  rating_change INTEGER,\n  metadata TEXT,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- achievement table\nCREATE TABLE achievement (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  icon TEXT NOT NULL,\n  status TEXT NOT NULL,\n  progress INTEGER NOT NULL,\n  target INTEGER NOT NULL,\n  xp_reward INTEGER NOT NULL,\n  category TEXT NOT NULL,\n  rarity TEXT NOT NULL,\n  requirements TEXT,\n  badge_color VARCHAR(255) NOT NULL,\n  completed_at INTEGER,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- skill_progression table\nCREATE TABLE skill_progression (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  category TEXT NOT NULL,\n  name VARCHAR(255) NOT NULL,\n  level INTEGER NOT NULL,\n  progress INTEGER NOT NULL,\n  xp INTEGER NOT NULL,\n  xp_to_next INTEGER NOT NULL,\n  improvement INTEGER NOT NULL,\n  color VARCHAR(255) NOT NULL,\n  icon TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- performance_analytics table\nCREATE TABLE performance_analytics (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  overall_rating INTEGER NOT NULL,\n  rating_history INTEGER NOT NULL,\n  peak_rating INTEGER NOT NULL,\n  peak_rating_date INTEGER NOT NULL,\n  game_stats TEXT NOT NULL,\n  time_control_stats TEXT NOT NULL,\n  recent_trend TEXT NOT NULL,\n  accuracy TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- study_streak table\nCREATE TABLE study_streak (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  current INTEGER NOT NULL,\n  longest INTEGER NOT NULL,\n  last_study_date INTEGER NOT NULL,\n  streak_start_date INTEGER NOT NULL,\n  days_to_milestone INTEGER NOT NULL,\n  next_milestone INTEGER NOT NULL,\n  status TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- goal table\nCREATE TABLE goal (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  target INTEGER NOT NULL,\n  progress INTEGER NOT NULL,\n  target_date INTEGER NOT NULL,\n  category TEXT NOT NULL,\n  priority TEXT NOT NULL,\n  status TEXT NOT NULL,\n  icon TEXT NOT NULL,\n  color VARCHAR(255) NOT NULL,\n  created_at INTEGER NOT NULL,\n  completed_at INTEGER,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- stats_cards_props table\nCREATE TABLE stats_cards_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  stats TEXT NOT NULL,\n  is_loading BOOLEAN,\n  time_period TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- progress_charts_props table\nCREATE TABLE progress_charts_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  rating_history INTEGER NOT NULL,\n  activity_data TEXT NOT NULL,\n  is_loading BOOLEAN,\n  time_period TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- activity_feed_props table\nCREATE TABLE activity_feed_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  sessions TEXT NOT NULL,\n  is_loading BOOLEAN,\n  max_sessions INTEGER,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- achievement_section_props table\nCREATE TABLE achievement_section_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  achievements TEXT NOT NULL,\n  is_loading BOOLEAN,\n  max_achievements INTEGER,\n  show_progress BOOLEAN,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- progress_overview_hook_return table\nCREATE TABLE progress_overview_hook_return (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  performance_analytics TEXT NOT NULL,\n  study_streak TEXT NOT NULL,\n  skill_progressions TEXT NOT NULL,\n  achievements TEXT NOT NULL,\n  goals TEXT NOT NULL,\n  learning_paths TEXT NOT NULL,\n  recent_sessions TEXT NOT NULL,\n  activity_data TEXT NOT NULL,\n  selected_time_period TEXT NOT NULL,\n  is_loading BOOLEAN NOT NULL,\n  set_time_period TEXT NOT NULL,\n  refresh_data TEXT NOT NULL,\n  stats_cards TEXT NOT NULL,\n  quick_actions TEXT NOT NULL,\n  weekly_progress TEXT NOT NULL,\n  format_rating INTEGER NOT NULL,\n  format_duration TEXT NOT NULL,\n  calculate_progress TEXT NOT NULL,\n  error VARCHAR(255) NOT NULL,\n  clear_error TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- mock_data_config table\nCREATE TABLE mock_data_config (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  skill_level TEXT NOT NULL,\n  rating_range INTEGER NOT NULL,\n  activity_multiplier INTEGER NOT NULL,\n  achievement_rate INTEGER NOT NULL,\n  streak_probability INTEGER NOT NULL,\n  PRIMARY KEY (id)\n);\n\n-- puzzle_stats table\nCREATE TABLE puzzle_stats (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  total_puzzles_completed INTEGER NOT NULL,\n  current_rating INTEGER NOT NULL,\n  weekly_progress INTEGER NOT NULL,\n  average_accuracy INTEGER NOT NULL,\n  time_spent INTEGER NOT NULL,\n  favorite_category VARCHAR(255) NOT NULL,\n  current_streak INTEGER NOT NULL,\n  best_streak INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- achievement table\nCREATE TABLE achievement (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  id VARCHAR(255) NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  icon VARCHAR(255) NOT NULL,\n  unlocked BOOLEAN NOT NULL,\n  unlocked_date TEXT,\n  rarity TEXT NOT NULL,\n  progress INTEGER,\n  max_progress INTEGER,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- stats_card_props table\nCREATE TABLE stats_card_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  stats TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- achievement_showcase_props table\nCREATE TABLE achievement_showcase_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  achievements TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- skill_level_option table\nCREATE TABLE skill_level_option (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  value TEXT NOT NULL,\n  label VARCHAR(255) NOT NULL,\n  description VARCHAR(255) NOT NULL,\n  icon TEXT NOT NULL,\n  rating INTEGER NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- study_progress table\nCREATE TABLE study_progress (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  user_id VARCHAR(255) NOT NULL,\n  total_study_time INTEGER NOT NULL,\n  current_streak INTEGER NOT NULL,\n  longest_streak INTEGER NOT NULL,\n  total_x_p INTEGER NOT NULL,\n  level INTEGER NOT NULL,\n  xp_to_next_level INTEGER NOT NULL,\n  path_progress TEXT NOT NULL,\n  achievements TEXT NOT NULL,\n  stats TEXT NOT NULL,\n  schedule TEXT,\n  recent_sessions TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\nALTER TABLE study_progress ADD FOREIGN KEY (user_id) REFERENCES user (id);\n\n-- progress_tracker_props table\nCREATE TABLE progress_tracker_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  progress TEXT NOT NULL,\n  current_path TEXT NOT NULL,\n  goals TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- achievement_badges_props table\nCREATE TABLE achievement_badges_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  badges TEXT NOT NULL,\n  recent_badges TEXT NOT NULL,\n  badge_progress TEXT NOT NULL,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- progress_tracker_props table\nCREATE TABLE progress_tracker_props (\n  id UUID NOT NULL DEFAULT gen_random_uuid(),\n  statistics TEXT NOT NULL,\n  achievements TEXT NOT NULL,\n  recent_progress TEXT NOT NULL,\n  learning_goals TEXT,\n  theme TEXT NOT NULL,\n  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id)\n);\n\n-- ========================================
